				t.Fatalf("Await = %v; progress:\n%s", err, progress.String())
			}
			if text := progress.String() + fmt.Sprint(err); !strings.Contains(text, test.want) {
				t.Fatalf("output %q lacks %q", text, test.want)
			}
		})
	}
}

