func TestSequenceSignerHTTPDurableMigrationAndConcurrentProducers(t *testing.T) {
	directory := t.TempDir()
	var lock sync.Mutex
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Header.Get("Authorization") == "" {
			http.Error(w, "unsigned OCI request", 401)
			return
		}
		sum := sha256.Sum256([]byte(r.URL.Path))
		name := filepath.Join(directory, hex.EncodeToString(sum[:]))
		lock.Lock()
		defer lock.Unlock()
		current, err := os.ReadFile(name)
		found := err == nil
		digest := sha256.Sum256(current)
		etag := fmt.Sprintf(`"%x"`, digest)
		switch r.Method {
		case "GET":
			if !found {
				http.NotFound(w, r)
				return
			}
			w.Header().Set("ETag", etag)
			w.Write(current)
		case "PUT":
			if r.Header.Get("If-None-Match") == "*" && found || r.Header.Get("If-Match") != "" && (!found || r.Header.Get("If-Match") != etag) {
				w.WriteHeader(412)
				return
			}
			if r.Header.Get("If-Match") == "" && r.Header.Get("If-None-Match") == "" {
				http.Error(w, "missing CAS", 400)
				return
			}
			body, err := io.ReadAll(r.Body)
			if err != nil {
				http.Error(w, err.Error(), 400)
				return
			}
			if err := os.WriteFile(name, body, 0600); err != nil {
				http.Error(w, err.Error(), 500)
				return
			}
			w.WriteHeader(200)
		default:
			w.WriteHeader(405)
		}
	}))
	defer server.Close()
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	keyPEM := pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})
	newLocation := func() SequenceLocation {
		client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(common.NewRawConfigurationProvider("tenancy", "user", "sa-saopaulo-1", "fingerprint", string(keyPEM), nil))
		if err != nil {
			t.Fatal(err)
		}
		client.Host = server.URL
		client.HTTPClient = sequenceHTTPClient{server}
		policy := common.NoRetryPolicy()
		client.SetCustomClientConfiguration(common.CustomClientConfiguration{RetryPolicy: &policy})
		return SequenceLocation{Client: client, Namespace: "ns", Bucket: "gru-1-head"}
	}
	rootPublic, root, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	public, signer, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	roots, _ := trust.ParseKeyring(rootPublic)
	keyID, _ := trust.KeyID(public)
	encoded, _ := trust.EncodeDelegatedPublicKey(public)
	now := time.Now().UTC().Truncate(time.Second)
	migration := SequenceMigration{Schema: SequenceMigrationSchema, Namespace: "ns", Bucket: "gru-1-head", Region: "GRU", Role: "orchestrator", Environment: "production", SequenceFloor: 900, SignerKeyID: keyID, SignerPublicKey: encoded}
	for _, cell := range []string{"GRU", "SFO", "FRA"} {
		migration.Regions = append(migration.Regions, SequenceFloor{Cell: cell, RunNumber: 900, IssuedAt: now, EvidenceSHA256: strings.Repeat("a", 64)})
	}
	envelope, err := SignSequenceMigration(migration, now, root)
	if err != nil {
		t.Fatal(err)
	}
	identity := SequenceIdentity{Role: "orchestrator", Environment: "production", SourceRevision: strings.Repeat("b", 40), ManifestSHA256: strings.Repeat("c", 64)}
	location := newLocation()
	if _, err := location.Allocate(t.Context(), identity, roots, signer); err != ErrSequenceMigrationRequired {
		t.Fatalf("unsigned initialization: %v", err)
	}
	var importers sync.WaitGroup
	importErrors := make(chan error, 8)
	for range 8 {
		importers.Go(func() {
			importErrors <- newLocation().ImportMigration(t.Context(), envelope, roots, identity.Role, identity.Environment, now)
		})
	}
	importers.Wait()
	close(importErrors)
	for err := range importErrors {
		if err != nil {
			t.Fatal(err)
		}
	}
	first, firstEvidence, err := location.AllocateWithEvidence(t.Context(), identity, roots, signer)
	if err != nil || first != 901 {
		t.Fatalf("first allocation %d: %v", first, err)
	}
	retry, retryEvidence, err := newLocation().AllocateWithEvidence(t.Context(), identity, roots, signer)
	if err != nil || retry != first || !bytes.Equal(firstEvidence, retryEvidence) {
		t.Fatalf("restart lost reservation %d: %v", retry, err)
	}
	var workers sync.WaitGroup
	sequences := make(chan uint64, 8)
	failures := make(chan error, 8)
	for index := range 8 {
		workers.Go(func() {
			candidate := identity
			candidate.ManifestSHA256 = fmt.Sprintf("%064x", index+1)
			sequence, evidence, err := newLocation().AllocateWithEvidence(t.Context(), candidate, roots, signer)
			if err != nil {
				failures <- err
				return
			}
			head, err := verifySequenceHead(evidence, roots, identity.Role, identity.Environment)
			if err != nil || head.Sequence != sequence || head.Identity != candidate {
				failures <- fmt.Errorf("winning reservation differs from returned allocation %d: %v", sequence, err)
				return
			}
			sequences <- sequence
		})
	}
	workers.Wait()
	close(sequences)
	close(failures)
	for err := range failures {
		t.Error(err)
	}
	seen := map[uint64]bool{}
	for sequence := range sequences {
		if sequence <= first || seen[sequence] {
			t.Errorf("duplicate or stale allocation %d", sequence)
		}
		seen[sequence] = true
	}
	if len(seen) != 8 {
		t.Fatalf("allocated %d sequences", len(seen))
	}
	retained, err := verifySequenceHead(firstEvidence, roots, identity.Role, identity.Environment)
	if err != nil || retained.Sequence != first || retained.Identity != identity {
		t.Fatalf("later allocations invalidated historical immutable family: %+v %v", retained, err)
	}
	// Immutable evidence must survive both SDK-client restart and head advancement.
	recovered, err := newLocation().retainReservation(t.Context(), retained, roots)
	if err != nil || !bytes.Equal(recovered, firstEvidence) {
		t.Fatalf("immutable allocation changed after restart: %v", err)
	}
	conflicting := retained
	conflicting.Identity.ManifestSHA256 = strings.Repeat("e", 64)
	payload, err := trust.EncodePayload(sequenceReservation{Sequence: conflicting.Sequence, Identity: conflicting.Identity})
	if err != nil {
		t.Fatal(err)
	}
	conflicting.Reservation, err = trust.Sign(payload, sequenceReservationScope(identity.Role, identity.Environment), now, now.Add(MaxReceiptLifetime), signer)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := newLocation().retainReservation(t.Context(), conflicting, roots); err == nil {
		t.Fatal("different signed family overwrote immutable winning reservation")
	}

	if err := location.ImportMigration(t.Context(), envelope, roots, identity.Role, identity.Environment, now); err != nil {
		t.Fatal(err)
	}
	if err := location.ImportMigration(t.Context(), envelope, roots, identity.Role, identity.Environment, now.Add(2*MaxSequenceMigrationLifetime)); err != nil {
		t.Fatalf("durable imported migration expired: %v", err)
	}
	alternate := location
	alternate.Namespace = "other"
	if err := alternate.ImportMigration(t.Context(), envelope, roots, identity.Role, identity.Environment, now); err == nil {
		t.Fatal("migration initialized a second allocator location")
	}
	candidate := identity
	candidate.ManifestSHA256 = strings.Repeat("d", 64)
	if sequence, err := newLocation().Allocate(t.Context(), candidate, roots, signer); err != nil || sequence != 910 {
		t.Fatalf("migration retry erased floor %d: %v", sequence, err)
	}
	_, otherSigner, _ := ed25519.GenerateKey(rand.Reader)
	if _, err := location.Allocate(t.Context(), candidate, roots, otherSigner); err == nil {
		t.Fatal("unapproved signer allocated")
	}
	verified, err := VerifySequenceMigrationHistorical(envelope, roots, identity.Role, identity.Environment)
	if err != nil {
		t.Fatal(err)
	}
	if !verified.AdmitsLegacyFloor("GRU", 900, now) || verified.AdmitsLegacyFloor("GRU", 901, now) || verified.AdmitsLegacyFloor("SFO", 0, now.Add(time.Second)) {
		t.Fatal("migration erased a retained floor")
	}
	// Unsigned head edits must fail even when they keep a plausible floor.
	entries, err := os.ReadDir(directory)
	if err != nil {
		t.Fatal(err)
	}
	for _, entry := range entries {
		path := filepath.Join(directory, entry.Name())
		wire, _ := os.ReadFile(path)
		var head sequenceHead
		if json.Unmarshal(wire, &head) == nil {
			head.Sequence++
			corrupt, _ := json.Marshal(head)
			if err := os.WriteFile(path, corrupt, 0600); err != nil {
				t.Fatal(err)
			}
		}
	}
	if _, err := location.Allocate(t.Context(), candidate, roots, signer); err == nil {
		t.Fatal("unsigned head mutation accepted")
	}
	rootAsSigner := migration
	rootAsSigner.SignerKeyID, _ = trust.KeyID(rootPublic)
	rootAsSigner.SignerPublicKey, _ = trust.EncodeDelegatedPublicKey(rootPublic)
	if _, err := SignSequenceMigration(rootAsSigner, now, root); err == nil {
		t.Fatal("offline root became online sequence signer")
	}
	incomplete := migration
	incomplete.Regions = incomplete.Regions[:2]
	if _, err := SignSequenceMigration(incomplete, now, root); err == nil {
		t.Fatal("incomplete regional migration accepted")
	}
	expired, _ := SignSequenceMigration(migration, now.Add(-2*MaxSequenceMigrationLifetime), root)
	if err := location.ImportMigration(t.Context(), expired, roots, identity.Role, identity.Environment, now); err == nil {
		t.Fatal("expired migration imported")
	}
}

type sequenceHTTPClient struct{ server *httptest.Server }

func (client sequenceHTTPClient) Do(request *http.Request) (*http.Response, error) {
	cloned := request.Clone(request.Context())
	address := *request.URL
	cloned.URL = &address
	cloned.URL.Scheme = "http"
	cloned.URL.Host = strings.TrimPrefix(client.server.URL, "http://")
	return client.server.Client().Do(cloned)
}

func SequenceObject(role, environment string) string {
	return "releases/sequences/" + environment + "/" + role + ".json"
}

// SequenceReservationObject retains an allocation independently of later heads.
func SequenceReservationObject(role, environment, migration string, sequence uint64) string {
	return fmt.Sprintf("releases/sequences/%s/%s/%s/%d.json", environment, role, migration, sequence)
}

type SequenceObjectClient interface {
	GetObject(context.Context, objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error)
	PutObject(context.Context, objectstorage.PutObjectRequest) (objectstorage.PutObjectResponse, error)
}

type SequenceLocation struct {
	Client    SequenceObjectClient
	Namespace string
	Bucket    string
}

type SequenceIdentity struct {
	Role           string `json:"role"`
	Environment    string `json:"environment"`
	SourceRevision string `json:"source_revision"`
	ManifestSHA256 string `json:"manifest_sha256"`
}

func (identity SequenceIdentity) validate() error {
	if !sequenceRole.MatchString(identity.Role) || validateEnvironment(identity.Environment) != nil || !ValidSourceRevision(identity.SourceRevision) || !digestPattern.MatchString(identity.ManifestSHA256) {
		return fmt.Errorf("%w: sequence allocation identity", ErrInvalidReceipt)
	}
	return nil
}

type sequenceReservation struct {
	Sequence uint64           `json:"sequence"`
	Identity SequenceIdentity `json:"identity"`
}

func sequenceReservationScope(role, environment string) trust.Scope {
	scope := SequenceMigrationScope(role, environment)
	scope.Domain = "terrascale.release.sequence-reservation"
	scope.Slot = "reservation"
	return scope
}

type sequenceHead struct {
	Schema      string           `json:"schema"`
	Sequence    uint64           `json:"sequence"`
	Identity    SequenceIdentity `json:"identity"`
	Migration   trust.Envelope   `json:"migration"`
	Reservation trust.Envelope   `json:"reservation"`
}

// Allocate reserves the next durable sequence before signing. A retry of the
// current reservation reuses it; abandoned reservations leave safe gaps.
func (location SequenceLocation) Allocate(ctx context.Context, identity SequenceIdentity, roots trust.Keyring, signer ed25519.PrivateKey) (uint64, error) {
	head, err := location.allocate(ctx, identity, roots, signer)
	return head.Sequence, err
}

// AllocateWithEvidence retains the exact winning reservation before any worker
// claim can be signed. A crash before retention leaves an unused sequence gap.
func (location SequenceLocation) AllocateWithEvidence(ctx context.Context, identity SequenceIdentity, roots trust.Keyring, signer ed25519.PrivateKey) (uint64, []byte, error) {
	head, err := location.allocate(ctx, identity, roots, signer)
	if err != nil {
		return 0, nil, err
	}
	wire, err := location.retainReservation(ctx, head, roots)
	if err != nil {
		return 0, nil, err
	}
	return head.Sequence, wire, nil
}

func (location SequenceLocation) allocate(ctx context.Context, identity SequenceIdentity, roots trust.Keyring, signer ed25519.PrivateKey) (sequenceHead, error) {
	if err := identity.validate(); err != nil {
		return sequenceHead{}, err
	}
	for range 32 {
		head, etag, found, err := location.read(ctx, identity.Role, identity.Environment, roots)
		if err != nil {
			return sequenceHead{}, err
		}
		if !found {
			return sequenceHead{}, ErrSequenceMigrationRequired
		}
		migration, err := VerifySequenceMigrationHistorical(head.Migration, roots, identity.Role, identity.Environment)
		if err != nil {
			return sequenceHead{}, err
		}
		if len(signer) != ed25519.PrivateKeySize {
			return sequenceHead{}, trust.ErrKeyMismatch
		}
		signerID, err := trust.KeyID(signer.Public().(ed25519.PublicKey))
		if err != nil || signerID != migration.SignerKeyID {
			return sequenceHead{}, trust.ErrKeyMismatch
		}
		if head.Identity == identity {
			return head, nil
		}
		if head.Sequence == math.MaxUint64 {
			return sequenceHead{}, fmt.Errorf("%w: sequence exhausted", ErrInvalidReceipt)
		}
		head.Sequence++
		head.Identity = identity
		payload, err := trust.EncodePayload(sequenceReservation{Sequence: head.Sequence, Identity: identity})
		if err != nil {
			return sequenceHead{}, err
		}
		now := time.Now().UTC()
		head.Reservation, err = trust.Sign(payload, sequenceReservationScope(identity.Role, identity.Environment), now, now.Add(MaxReceiptLifetime), signer)
		if err != nil {
			return sequenceHead{}, err
		}
		if err := location.write(ctx, identity.Role, identity.Environment, head, etag); errors.Is(err, ErrSequenceConflict) {
			continue
		} else if err != nil {
			return sequenceHead{}, err
		}
		return head, nil
	}
	return sequenceHead{}, ErrSequenceConflict
}

// ImportMigration creates the ordering namespace once. A different migration
// never overwrites an allocated sequence or an earlier migration.
func (location SequenceLocation) ImportMigration(ctx context.Context, envelope trust.Envelope, roots trust.Keyring, role, environment string, now time.Time) error {
	migration, err := VerifySequenceMigrationHistorical(envelope, roots, role, environment)
	if err != nil {
		return err
	}
	if migration.Namespace != location.Namespace || migration.Bucket != location.Bucket {
		return fmt.Errorf("%w: migration sequence location", ErrInvalidReceipt)
	}
	head, etag, found, err := location.read(ctx, role, environment, roots)
	if err != nil {
		return err
	}
	if found {
		existing, _ := trust.Fingerprint(head.Migration)
		incoming, _ := trust.Fingerprint(envelope)
		if existing == incoming {
			return nil
		}
		return fmt.Errorf("%w: namespace already migrated", ErrSequenceConflict)
	}
	if _, err := VerifySequenceMigrationCurrent(envelope, roots, role, environment, now); err != nil {
		return err
	}
	err = location.write(ctx, role, environment, sequenceHead{Schema: "terrascale.release.sequence.v1", Sequence: migration.SequenceFloor, Migration: envelope}, etag)
	if !errors.Is(err, ErrSequenceConflict) {
		return err
	}
	// Another producer may initialize the exact same grant concurrently.
	head, _, found, err = location.read(ctx, role, environment, roots)
	if err != nil {
		return err
	}
	if found {
		retained, _ := trust.Fingerprint(head.Migration)
		incoming, _ := trust.Fingerprint(envelope)
		if retained == incoming {
			return nil
		}
	}
	return ErrSequenceConflict
}

func (location SequenceLocation) read(ctx context.Context, role, environment string, roots trust.Keyring) (sequenceHead, string, bool, error) {
	var head sequenceHead
	if location.Client == nil || location.Namespace == "" || location.Bucket == "" {
		return head, "", false, fmt.Errorf("%w: sequence location", ErrInvalidReceipt)
	}
	name := SequenceObject(role, environment)
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name})
	if sequenceHTTPStatus(err) == http.StatusNotFound {
		return head, "", false, nil
	}
	if err != nil {
		return head, "", false, err
	}
	defer response.Content.Close()
	wire, err := io.ReadAll(io.LimitReader(response.Content, trust.MaxEnvelopeBytes+1))
	if err != nil {
		return head, "", false, err
	}
	head, err = verifySequenceHead(wire, roots, role, environment)
	if err != nil {
		return head, "", false, err
	}
	migration, err := VerifySequenceMigrationHistorical(head.Migration, roots, role, environment)
	if err != nil {
		return head, "", false, err
	}
	if migration.Namespace != location.Namespace || migration.Bucket != location.Bucket || response.ETag == nil || *response.ETag == "" {
		return head, "", false, fmt.Errorf("%w: migration sequence location or ETag", ErrInvalidReceipt)
	}
	return head, *response.ETag, true, nil
}

func (location SequenceLocation) write(ctx context.Context, role, environment string, head sequenceHead, etag string) error {
	wire, err := json.Marshal(head, json.Deterministic(true))
	if err != nil {
		return err
	}
	name := SequenceObject(role, environment)
	request := objectstorage.PutObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name, ContentLength: new(int64(len(wire))), PutObjectBody: io.NopCloser(bytes.NewReader(wire)), ContentType: new("application/json")}
	if etag == "" {
		request.IfNoneMatch = new("*")
	} else {
		request.IfMatch = &etag
	}
	_, err = location.Client.PutObject(ctx, request)
	if sequenceHTTPStatus(err) == http.StatusPreconditionFailed {
		return ErrSequenceConflict
	}
	return err
}

func sequenceHTTPStatus(err error) int {
	if service, ok := errors.AsType[interface {
		error
		GetHTTPStatusCode() int
	}](err); ok {
		return service.GetHTTPStatusCode()
	}
	return 0
}

func verifySequenceHead(wire []byte, roots trust.Keyring, role, environment string) (sequenceHead, error) {
	var head sequenceHead
	if err := protocol.DecodeStrict(wire, &head, trust.MaxEnvelopeBytes); err != nil {
		return head, err
	}
	migration, err := VerifySequenceMigrationHistorical(head.Migration, roots, role, environment)
	if err != nil {
		return head, err
	}
	if head.Schema != "terrascale.release.sequence.v1" || head.Sequence < migration.SequenceFloor {
		return head, fmt.Errorf("%w: sequence head", ErrInvalidReceipt)
	}
	if head.Identity != (SequenceIdentity{}) {
		if err := head.Identity.validate(); err != nil {
			return head, err
		}
		if head.Identity.Role != role || head.Identity.Environment != environment || head.Sequence == migration.SequenceFloor {
			return head, fmt.Errorf("%w: sequence identity scope", ErrInvalidReceipt)
		}
	} else if head.Sequence != migration.SequenceFloor {
		return head, fmt.Errorf("%w: missing sequence identity", ErrInvalidReceipt)
	}
	if head.Identity != (SequenceIdentity{}) {
		public, _ := base64.RawURLEncoding.Strict().DecodeString(migration.SignerPublicKey)
		payload, err := trust.VerifyHistorical(head.Reservation, sequenceReservationScope(role, environment), trust.Keyring{migration.SignerKeyID: ed25519.PublicKey(public)}, trust.Policy{MaxLifetime: MaxReceiptLifetime})
		if err != nil {
			return head, err
		}
		reservation, err := decodeCanonicalPayload[sequenceReservation](payload)
		if err != nil {
			return head, err
		}
		if reservation.Sequence != head.Sequence || reservation.Identity != head.Identity {
			return head, fmt.Errorf("%w: unauthenticated sequence head", ErrInvalidReceipt)
		}
	}
	return head, nil
}

func (location SequenceLocation) retainReservation(ctx context.Context, head sequenceHead, roots trust.Keyring) ([]byte, error) {
	wire, err := json.Marshal(head, json.Deterministic(true))
	if err != nil {
		return nil, err
	}
	if len(wire) > MaxWorkerFamilyEvidenceBytes {
		return nil, fmt.Errorf("%w: sequence evidence size", ErrInvalidReceipt)
	}
	migration, err := trust.Fingerprint(head.Migration)
	if err != nil {
		return nil, err
	}
	name := SequenceReservationObject(head.Identity.Role, head.Identity.Environment, migration, head.Sequence)
	_, err = location.Client.PutObject(ctx, objectstorage.PutObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name, ContentLength: new(int64(len(wire))), PutObjectBody: io.NopCloser(bytes.NewReader(wire)), ContentType: new("application/json"), IfNoneMatch: new("*")})
	if err == nil {
		return wire, nil
	}
	if sequenceHTTPStatus(err) != http.StatusPreconditionFailed {
		return nil, err
	}
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name})
	if err != nil {
		return nil, err
	}
	if response.Content == nil {
		return nil, fmt.Errorf("%w: retained sequence reservation has no body", ErrInvalidReceipt)
	}
	defer response.Content.Close()
	retained, err := io.ReadAll(io.LimitReader(response.Content, MaxWorkerFamilyEvidenceBytes+1))
	if err != nil {
		return nil, err
	}
	if len(retained) > MaxWorkerFamilyEvidenceBytes {
		return nil, fmt.Errorf("%w: sequence evidence size", ErrInvalidReceipt)
	}
	previous, err := verifySequenceHead(retained, roots, head.Identity.Role, head.Identity.Environment)
	if err != nil {
		return nil, err
	}
	previousMigration, err := trust.Fingerprint(previous.Migration)
	if err != nil {
		return nil, err
	}
	if previousMigration != migration || previous.Sequence != head.Sequence || previous.Identity != head.Identity {
		return nil, ErrSequenceConflict
	}
	return retained, nil
}

func (migration SequenceMigration) Validate() error {
	if migration.Schema != SequenceMigrationSchema || migration.Namespace == "" || len(migration.Namespace) > 128 || migration.Bucket != "gru-1-head" || migration.Region != "GRU" || !sequenceRole.MatchString(migration.Role) || validateEnvironment(migration.Environment) != nil || migration.SequenceFloor == 0 || len(migration.Regions) != 3 {
		return fmt.Errorf("%w: sequence migration scope or regional floors", ErrInvalidReceipt)
	}
	public, err := base64.RawURLEncoding.Strict().DecodeString(migration.SignerPublicKey)
	if err != nil || len(public) != ed25519.PublicKeySize {
		return fmt.Errorf("%w: sequence signer", ErrInvalidReceipt)
	}
	keyID, err := trust.KeyID(ed25519.PublicKey(public))
	if err != nil || keyID != migration.SignerKeyID {
		return trust.ErrKeyMismatch
	}
	seen := make(map[string]bool, 3)
	for _, floor := range migration.Regions {
		if !ValidRegion(floor.Cell) || seen[floor.Cell] || floor.RunNumber < 0 || uint64(floor.RunNumber) > migration.SequenceFloor || !digestPattern.MatchString(floor.EvidenceSHA256) || (floor.RunNumber == 0 && floor.IssuedAt.IsZero()) || (!floor.IssuedAt.IsZero() && floor.IssuedAt.Location() != time.UTC) {
			return fmt.Errorf("%w: sequence migration regional floor", ErrInvalidReceipt)
		}
		seen[floor.Cell] = true
	}
	return nil
}

func SequenceMigrationScope(role, environment string) trust.Scope {
	return trust.Scope{Domain: SequenceMigrationDomain, DeploymentID: entityid.Derive("release-sequence", role, environment), Cell: "global", Environment: environment, Role: role, Slot: "migration"}
}

func SignSequenceMigration(migration SequenceMigration, now time.Time, root ed25519.PrivateKey) (trust.Envelope, error) {
	if err := migration.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if len(root) != ed25519.PrivateKeySize {
		return trust.Envelope{}, trust.ErrInvalid
	}
	rootID, err := trust.KeyID(root.Public().(ed25519.PublicKey))
	if err != nil {
		return trust.Envelope{}, err
	}
	if rootID == migration.SignerKeyID {
		return trust.Envelope{}, fmt.Errorf("%w: online sequence signer must differ from offline root", ErrInvalidReceipt)
	}
	payload, err := trust.EncodePayload(migration)
	if err != nil {
		return trust.Envelope{}, err
	}
	return trust.Sign(payload, SequenceMigrationScope(migration.Role, migration.Environment), now, now.Add(MaxSequenceMigrationLifetime), root)
}

// VerifySequenceMigrationHistorical checks a durable authorization already
// imported by the signer; importing a new migration requires current validity.
func VerifySequenceMigrationHistorical(envelope trust.Envelope, roots trust.Keyring, role, environment string) (SequenceMigration, error) {
	return verifySequenceMigration(envelope, roots, role, environment, time.Time{})
}

func VerifySequenceMigrationCurrent(envelope trust.Envelope, roots trust.Keyring, role, environment string, now time.Time) (SequenceMigration, error) {
	if now.IsZero() {
		return SequenceMigration{}, fmt.Errorf("%w: migration verification time", ErrInvalidReceipt)
	}
	return verifySequenceMigration(envelope, roots, role, environment, now)
}

func verifySequenceMigration(envelope trust.Envelope, roots trust.Keyring, role, environment string, now time.Time) (SequenceMigration, error) {
	scope := SequenceMigrationScope(role, environment)
	policy := trust.Policy{MaxLifetime: MaxSequenceMigrationLifetime}
	var payload []byte
	var err error
	if now.IsZero() {
		payload, err = trust.VerifyHistorical(envelope, scope, roots, policy)
	} else {
		payload, err = trust.VerifyCurrent(envelope, scope, roots, now, policy)
	}
	if err != nil {
		return SequenceMigration{}, err
	}
	migration, err := decodeCanonicalPayload[SequenceMigration](payload)
	if err != nil {
		return SequenceMigration{}, err
	}
	if err := migration.Validate(); err != nil {
		return SequenceMigration{}, err
	}
	if roots[migration.SignerKeyID] != nil {
		return SequenceMigration{}, fmt.Errorf("%w: sequence signer is an offline root", ErrInvalidReceipt)
	}
	if migration.Role != role || migration.Environment != environment {
		return SequenceMigration{}, trust.ErrScopeMismatch
	}
	return migration, nil
}

// AdmitsLegacyFloor ensures a migration cannot erase the consumer's retained
// ordering floor, even if its current channel object has been replaced.
func (migration SequenceMigration) AdmitsLegacyFloor(cell string, run int64, issued time.Time) bool {
	for _, floor := range migration.Regions {
		if floor.Cell == cell {
			return run <= floor.RunNumber && (issued.IsZero() || !floor.IssuedAt.IsZero() && !issued.After(floor.IssuedAt))
		}
	}
	return false
}

func ReadObject(ctx context.Context, client objectReader, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	switch sdk := client.(type) {
	case objectstorage.ObjectStorageClient:
		ConfigureReadCancellation(&sdk.BaseClient)
		return sdk.GetObject(ReadContext(ctx), request)
	case *objectstorage.ObjectStorageClient:
		copy := *sdk
		ConfigureReadCancellation(&copy.BaseClient)
		return copy.GetObject(ReadContext(ctx), request)
	default:
		return client.GetObject(ctx, request)
	}
}

// RequestContext keeps the SDK retry goroutine joined while the original context
// cancels the HTTP request and backoff. Use with ConfigureRequestCancellation.
func RequestContext(ctx context.Context) context.Context {
	if originalReadContext(ctx) != nil && ctx.Done() == nil {
		return ctx
	}
	return context.WithValue(context.WithoutCancel(ctx), readContextKey{}, ctx)
}

// ReadContext is RequestContext for existing read callers.
func ReadContext(ctx context.Context) context.Context { return RequestContext(ctx) }

type readContextKey struct{}

func originalReadContext(ctx context.Context) context.Context {
	original, _ := ctx.Value(readContextKey{}).(context.Context)
	return original
}

// ConfigureReadCancellation is retained for existing read callers.
func ConfigureReadCancellation(client *common.BaseClient) { ConfigureRequestCancellation(client) }

// ConfigureRequestCancellation must run after other interceptors are installed.
// It avoids the SDK Retry response race while preserving wire cancellation.
func ConfigureRequestCancellation(client *common.BaseClient) {
	if readCancellationConfigured(client.HTTPClient) {
		return
	}
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		if original := originalReadContext(request.Context()); original != nil {
			*request = *request.WithContext(context.WithValue(original, readContextKey{}, original))
		}
		if previous != nil {
			return previous(request)
		}
		return request.Context().Err()
	}
	client.HTTPClient = readDispatcher{next: client.HTTPClient}
}

func readCancellationConfigured(dispatcher common.HTTPRequestDispatcher) bool {
	switch dispatcher := dispatcher.(type) {
	case readDispatcher:
		return true
	case *instrumentedDispatcher:
		return readCancellationConfigured(dispatcher.next)
	default:
		return false
	}
}

type readDispatcher struct{ next common.HTTPRequestDispatcher }

type readTransportError struct {
	err error
	ctx context.Context
}

func (e *readTransportError) Error() string { return e.err.Error() }
func (e *readTransportError) Unwrap() error { return e.err }

func (d readDispatcher) Do(request *http.Request) (*http.Response, error) {
	var finish func(*http.Response, error, bool) error
	if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
		deadline := new(admissionDeadline)
		*request = *request.WithContext(context.WithValue(request.Context(), admissionDeadlineKey{}, deadline))
		if begin, ok := request.Context().Value(wireAttemptKey{}).(func(*http.Request) (func(*http.Response, error, bool) error, error)); ok {
			if begin == nil {
				return nil, errors.New("OCI wire attempt journal is unavailable")
			}
			var err error
			finish, err = begin(request)
			if err != nil {
				return nil, fmt.Errorf("OCI wire attempt checkpoint: %w", err)
			}
			if finish == nil {
				return nil, errors.New("OCI wire attempt journal lacks outcome recorder")
			}
		}
		deny := func(err error) (*http.Response, error) {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, err
		}
		if finish != nil {
			if err := request.Context().Err(); err != nil {
				return deny(err)
			}
			// The durable begin may block; refresh the claim after that write.
			if guard, ok := request.Context().Value(authorityKey{}).(func(context.Context) error); ok {
				if guard == nil {
					return deny(errors.New("OCI wire authority is unavailable"))
				}
				if err := guard(request.Context()); err != nil {
					return deny(fmt.Errorf("OCI wire authority: %w", err))
				}
			}
		}
		if acquire, ok := request.Context().Value(admissionKey{}).(func(context.Context) (func(), error)); ok {
			if acquire == nil {
				return deny(errors.New("OCI write admission is unavailable"))
			}
			release, err := acquire(request.Context())
			if err != nil {
				return deny(fmt.Errorf("OCI write admission: %w", err))
			}
			if release == nil {
				return deny(errors.New("OCI write admission did not fence current authority"))
			}
			defer release()
		}
		if err := request.Context().Err(); err != nil {
			return deny(err)
		}
		if !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
			return deny(errors.New("OCI current admission facts expired before dispatch"))
		}
	}
	if guard, ok := request.Context().Value(requestGuardKey{}).(func(context.Context) error); ok {
		var err error
		if guard == nil {
			err = errors.New("OCI request session is unavailable")
		} else {
			// Authorization may itself read OCI; those reads must not recurse
			// into the guard they are currently establishing.
			err = guard(context.WithValue(request.Context(), requestGuardKey{}, struct{}{}))
		}
		if err != nil {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, &readTransportError{err: err, ctx: request.Context()}
		}
	}
	// The final source guard may wait past a shorter retained admission cap.
	// Recheck it after that wait, immediately before the actual dispatch.
	finalErr := request.Context().Err()
	if deadline, ok := request.Context().Value(admissionDeadlineKey{}).(*admissionDeadline); ok && !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
		finalErr = errors.Join(finalErr, errors.New("OCI original admission deadline expired during final source guard"))
	}
	if finalErr != nil {
		if finish != nil {
			finalErr = errors.Join(finalErr, finish(nil, finalErr, false))
		}
		return nil, &readTransportError{err: finalErr, ctx: request.Context()}
	}
	response, err := d.next.Do(request)
	if finish != nil {
		if recordErr := finish(response, err, true); recordErr != nil {
			if response != nil && response.Body != nil {
				_ = response.Body.Close()
			}
			err = errors.Join(err, fmt.Errorf("OCI wire outcome remains unknown: %w", recordErr))
		}
	}
	if original := originalReadContext(request.Context()); original != nil && err != nil {
		return response, &readTransportError{err: err, ctx: original}
	}
	return response, err
}

func SourceTreeDigest(ctx context.Context, checkout, commit string) (string, error) {
	if !ValidSourceRevision(commit) {
		return "", errors.New("--commit must be a full lowercase commit SHA")
	}
	// Archive from an empty repository that borrows the checkout's objects,
	// so no attributes from outside the commit (info/attributes,
	// core.attributesFile, the system file) apply, and pin the file modes.
	// No inherited GIT_* variable reaches git.
	env := []string{"GIT_ATTR_NOSYSTEM=1"}
	for _, variable := range os.Environ() {
		if !strings.HasPrefix(variable, "GIT_") {
			env = append(env, variable)
		}
	}
	git := func(args ...string) *exec.Cmd {
		command := exec.CommandContext(ctx, "git", args...)
		command.Env = env
		return command
	}
	objects, err := git("-C", checkout, "rev-parse", "--path-format=absolute", "--git-path", "objects").Output()
	if err != nil {
		return "", fmt.Errorf("find the objects of %s: %w", checkout, err)
	}
	isolated, err := os.MkdirTemp("", "ts-source-tree-")
	if err != nil {
		return "", err
	}
	defer os.RemoveAll(isolated)
	// The empty repository and its archive read no system or global
	// config (an init.templateDir could bring info/attributes) and no
	// template; reading the checkout may still need the user's safe.directory.
	isolate := func(command *exec.Cmd) *exec.Cmd {
		command.Env = append(command.Env, "GIT_CONFIG_NOSYSTEM=1", "GIT_CONFIG_GLOBAL=/dev/null")
		return command
	}
	if out, err := isolate(git("init", "-q", "--bare", "--template=", isolated)).CombinedOutput(); err != nil {
		return "", fmt.Errorf("prepare the source archive: %w: %s", err, out)
	}
	command := isolate(git("--git-dir", isolated, "-c", "tar.umask=0002", "-c", "core.attributesFile=/dev/null",
		"archive", "--format=tar", commit+"^{commit}"))
	command.Env = append(command.Env, "GIT_ALTERNATE_OBJECT_DIRECTORIES="+strings.TrimSpace(string(objects)))
	stdout, err := command.StdoutPipe()
	if err != nil {
		return "", err
	}
	if err := command.Start(); err != nil {
		return "", err
	}
	hash := sha256.New()
	_, copyErr := io.Copy(hash, stdout)
	if err := errors.Join(copyErr, command.Wait()); err != nil {
		return "", fmt.Errorf("archive source %s: %w", commit, err)
	}
	return hex.EncodeToString(hash.Sum(nil)), nil
}

)

