// BucketName is the head bucket of the cell's region, e.g. gru-1-head.
func BucketName(cell string) (string, error) {
	if !release.ValidRegion(cell) {
		return "", fmt.Errorf("%w: cell %q", ErrInvalid, cell)
	}
	name, err := naming.RegionCell(cell).Name()
	if err != nil {
		return "", err
	}
	return name + "-head", nil
}

// Verify checks every receipt against the consumer's roots, environment and
// cell, and that all of them name the channel's source revision and run.
// It returns the verified binaries by architecture.
func (channel Channel) Verify(roots trust.Keyring, cell, environment string, now time.Time) (map[string]release.VerifiedBinary, error) {
	if channel.Schema != ChannelSchema || channel.Cell != cell || channel.Environment != environment ||
		!release.ValidSourceRevision(channel.SourceRevision) || channel.RunNumber <= 0 ||
		len(channel.Receipts) == 0 || len(channel.Receipts) > 2 {
		return nil, fmt.Errorf("%w: channel scope", ErrInvalid)
	}
	var migrationDigest, sequenceSigner string
	if channel.ReleaseSequence > 0 {
		envelope, err := trust.DecodeEnvelope(channel.SequenceMigration)
		if err != nil {
			return nil, err
		}
		migration, err := release.VerifySequenceMigrationHistorical(envelope, roots, "orchestrator", environment)
		if err != nil {
			return nil, err
		}
		if channel.ReleaseSequence <= migration.SequenceFloor {
			return nil, fmt.Errorf("%w: release sequence does not exceed migration floor", ErrInvalid)
		}
		sequenceSigner = migration.SignerKeyID
		migrationDigest, err = trust.Fingerprint(envelope)
		if err != nil {
			return nil, err
		}
	} else if len(channel.SequenceMigration) > 0 {
		return nil, fmt.Errorf("%w: legacy channel carries sequence migration", ErrInvalid)
	}
	verified := make(map[string]release.VerifiedBinary, len(channel.Receipts))
	for _, wire := range channel.Receipts {
		envelope, err := trust.DecodeEnvelope(wire)
		if err != nil {
			return nil, err
		}
		if channel.ReleaseSequence > 0 && envelope.KeyID != sequenceSigner {
			return nil, fmt.Errorf("%w: receipt signer does not own release order", ErrInvalid)
		}
		architecture, _ := strings.CutPrefix(envelope.Scope.Slot, "linux-")
		if _, seen := verified[architecture]; seen {
			return nil, fmt.Errorf("%w: two receipts for %s", ErrInvalid, architecture)
		}
		binary, err := release.VerifyQualifiedBinaryUpdateCurrent(wire, channel.Delegation, roots,
			release.UpdateExpectation{Environment: environment, Cell: cell, Architecture: architecture}, now)
		if err != nil {
			return nil, err
		}
		// The payload is authentic now; its lineage carries the signed run.
		var receipt release.BinaryUpdateReceipt
		if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
			return nil, err
		}
		if binary.Receipt().SourceRevision != channel.SourceRevision || receipt.Lineage.QualificationRunNum != channel.RunNumber || receipt.ReleaseSequence != channel.ReleaseSequence || receipt.SequenceMigrationSHA256 != migrationDigest {
			return nil, fmt.Errorf("%w: receipt for %s names another release", ErrInvalid, architecture)
		}
		verified[architecture] = binary
	}
	return verified, nil
}

// ReleasePins protects rollback targets and withdrawn binaries from CI
// pruning. A nil pointer means the leader has not published pins yet;
// an empty value means it read the cell's state and found none.
type ReleasePins struct {
	Rollback []string `json:"rollback"`
	KnownBad []string `json:"known_bad"`
}

func (pins *ReleasePins) Equal(other *ReleasePins) bool {
	if pins == nil || other == nil {
		return pins == other
	}
	return slices.Equal(pins.Rollback, other.Rollback) && slices.Equal(pins.KnownBad, other.KnownBad)
}

// Validate refuses an absent inventory or digests the pruning script would
// silently skip. Status comes from a remote bucket, not trusted cell state.
func (pins *ReleasePins) Validate() error {
	if pins == nil {
		return fmt.Errorf("%w: release pins are missing", ErrInvalid)
	}
	for _, digests := range [][]string{pins.Rollback, pins.KnownBad} {
		for _, digest := range digests {
			if _, err := hex.DecodeString(digest); err != nil || len(digest) != 64 || strings.ToLower(digest) != digest {
				return fmt.Errorf("%w: release pin %q", ErrInvalid, digest)
			}
		}
	}
	return nil
}

func Publish(ctx context.Context, location Location, channel Channel) error {
	wire, err := json.Marshal(channel, json.Deterministic(true))
	if err != nil {
		return err
	}
	for range 3 {
		current, etag, found, err := location.get(ctx, ChannelObject, MaxChannelBytes)
		if err != nil {
			return err
		}
		if found {
			var existing Channel
			if err := json.Unmarshal(current, &existing); err != nil {
				return fmt.Errorf("decode the current release channel: %w", err)
			}
			if err := compareChannelOrder(existing, channel); err != nil {
				return err
			}
		}
		if err := location.put(ctx, ChannelObject, wire, etag); !errors.Is(err, ErrConflict) {
			return err
		}
	}
	return ErrConflict
}

// ReadChannel returns the region's channel; found is false when it has none.
func ReadChannel(ctx context.Context, location Location) (Channel, bool, error) {
	var channel Channel
	found, err := location.read(ctx, ChannelObject, MaxChannelBytes, &channel)
	return channel, found, err
}

// ReadStatus returns the region's status; found is false when it has none.
// Unknown fields are ignored: a region may run an older or newer binary.
func ReadStatus(ctx context.Context, location Location) (Status, bool, error) {
	var status Status
	found, err := location.read(ctx, StatusObject, maxStatusBytes, &status)
	return status, found, err
}

// WriteStatus replaces the region's status. Only the region's authority
// leader writes it, and a report is telemetry, so it is not conditional.
func WriteStatus(ctx context.Context, location Location, status Status) error {
	status.Schema, status.Reason = StatusSchema, Clip(status.Reason)
	wire, err := json.Marshal(status, json.Deterministic(true))
	if err != nil {
		return err
	}
	return location.write(ctx, StatusObject, wire)
}

// write replaces name unconditionally.
func (location Location) write(ctx context.Context, name string, wire []byte) error {
	if len(wire) > maxStatusBytes {
		return fmt.Errorf("%w: %s exceeds %d bytes", ErrInvalid, name, maxStatusBytes)
	}
	_, err := location.Client.PutObject(ctx, objectstorage.PutObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
		ContentLength: new(int64(len(wire))), PutObjectBody: io.NopCloser(bytes.NewReader(wire)),
		ContentType: new("application/json"),
	})
	if err != nil {
		return fmt.Errorf("write %s/%s: %w", location.Bucket, name, err)
	}
	return nil
}

func Await(ctx context.Context, location Location, channel Channel, poll time.Duration, deadline time.Time,
	progress io.Writer,
) error {
	var last string
	for {
		status, found, err := ReadStatus(ctx, location)
		line := "waiting for the region to report"
		switch {
		case err != nil:
			line = "status read failed: " + err.Error()
		case !found || channel.ReleaseSequence > 0 && status.ReleaseSequence < channel.ReleaseSequence || channel.ReleaseSequence == 0 && status.ReleaseSequence == 0 && status.RunNumber < channel.RunNumber:
		case status.ReleaseSequence > channel.ReleaseSequence || channel.ReleaseSequence == 0 && status.RunNumber > channel.RunNumber:
			return fmt.Errorf("%w: %s moved on to run %d", ErrFailed, channel.Cell, status.RunNumber)
		case status.Cell != channel.Cell || status.SourceRevision != channel.SourceRevision:
			return fmt.Errorf("%w: %s reports run %d for %s %s", ErrFailed, channel.Cell, status.RunNumber,
				Clip(status.Cell), Clip(status.SourceRevision))
		case status.State == StateComplete:
			fmt.Fprintf(progress, "%s complete: run %d %s\n", channel.Cell, channel.RunNumber, channel.SourceRevision)
			return nil
		case status.State == StateFailed:
			return fmt.Errorf("%w: %s rolled back run %d: %s", ErrFailed, channel.Cell, channel.RunNumber, Clip(status.Reason))
		default:
			line = Clip(string(status.State) + " " + status.Reason)
		}
		if line != last {
			fmt.Fprintf(progress, "%s %s\n", channel.Cell, line)
			last = line
		}
		if !time.Now().Before(deadline) {
			return fmt.Errorf("%w: %s did not complete run %d in time (%s)", ErrFailed, channel.Cell, channel.RunNumber, line)
		}
		select {
		case <-ctx.Done():
			if !time.Now().Before(deadline) {
				return fmt.Errorf("%w: %s did not complete run %d in time (%s)", ErrFailed, channel.Cell, channel.RunNumber, line)
			}
			return ctx.Err()
		case <-time.After(min(poll, time.Until(deadline))):
		}
	}
}

// Clip makes region-written text safe for a CI log: one line, no control
// or bidirectional formatting characters, at most maxReason characters.
func Clip(text string) string {
	runes := []rune(text)
	if len(runes) > maxReason {
		runes = append(runes[:maxReason], []rune("...")...)
	}
	for index, r := range runes {
		if unicode.IsControl(r) || unicode.In(r, unicode.Bidi_Control, unicode.Zl, unicode.Zp) {
			runes[index] = ' '
		}
	}
	return string(runes)
}

func (location Location) read(ctx context.Context, name string, limit int64, value any) (bool, error) {
	data, _, found, err := location.get(ctx, name, limit)
	if err != nil || !found {
		return found, err
	}
	if err := json.Unmarshal(data, value); err != nil {
		return true, fmt.Errorf("%w: decode %s: %w", ErrInvalid, name, err)
	}
	return true, nil
}

func (location Location) get(ctx context.Context, name string, limit int64) ([]byte, string, bool, error) {
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
	})
	if httpStatus(err) == http.StatusNotFound {
		return nil, "", false, nil
	}
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	defer response.Content.Close()
	data, err := io.ReadAll(io.LimitReader(response.Content, limit+1))
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	if int64(len(data)) > limit {
		return nil, "", false, fmt.Errorf("%w: %s/%s exceeds %d bytes", ErrInvalid, location.Bucket, name, limit)
	}
	if response.ETag == nil || *response.ETag == "" {
		return nil, "", false, fmt.Errorf("read %s/%s: no ETag", location.Bucket, name)
	}
	return data, *response.ETag, true, nil
}

// put writes data only if the object still has etag, or does not exist when
// etag is empty.
func (location Location) put(ctx context.Context, name string, data []byte, etag string) error {
	request := objectstorage.PutObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
		ContentLength: new(int64(len(data))), PutObjectBody: io.NopCloser(bytes.NewReader(data)),
		ContentType: new("application/json"),
	}
	if etag == "" {
		request.IfNoneMatch = new("*")
	} else {
		request.IfMatch = &etag
	}
	_, err := location.Client.PutObject(ctx, request)
	if httpStatus(err) == http.StatusPreconditionFailed {
		return ErrConflict
	}
	if err != nil {
		return fmt.Errorf("write %s/%s: %w", location.Bucket, name, err)
	}
	return nil
}

func httpStatus(err error) int {
	if serviceErr, ok := errors.AsType[interface {
		error
		GetHTTPStatusCode() int
	}](err); ok {
		return serviceErr.GetHTTPStatusCode()
	}
	return 0
}

func compareChannelOrder(existing, next Channel) error {
	switch {
	case existing.ReleaseSequence > 0:
		if next.ReleaseSequence < existing.ReleaseSequence {
			return ErrStale
		}
		if next.ReleaseSequence == existing.ReleaseSequence && (next.SourceRevision != existing.SourceRevision || next.RunNumber != existing.RunNumber) {
			return fmt.Errorf("%w: sequence already names another release", ErrInvalid)
		}
		if next.ReleaseSequence == existing.ReleaseSequence {
			previous, err := channelBinaryIdentities(existing)
			if err != nil {
				return err
			}
			incoming, err := channelBinaryIdentities(next)
			if err != nil {
				return err
			}
			if !maps.Equal(previous, incoming) {
				return fmt.Errorf("%w: sequence already names another artifact", ErrInvalid)
			}
		}
	case next.ReleaseSequence > 0:
		envelope, err := trust.DecodeEnvelope(next.SequenceMigration)
		if err != nil {
			return err
		}
		// Publish receives an already verified channel; the root signature is
		// checked by Channel.Verify at the admission boundary.
		var migration release.SequenceMigration
		if err := protocol.DecodeStrict(envelope.Payload, &migration, trust.MaxPayloadBytes); err != nil {
			return err
		}
		if err := migration.Validate(); err != nil {
			return err
		}
		if migration.Role != "orchestrator" || migration.Environment != next.Environment || next.ReleaseSequence <= migration.SequenceFloor || !migration.AdmitsLegacyFloor(next.Cell, existing.RunNumber, time.Time{}) {
			return fmt.Errorf("%w: migration does not cover retained channel floor", ErrStale)
		}
	default:
		if existing.RunNumber > next.RunNumber {
			return ErrStale
		}
		if existing.RunNumber == next.RunNumber && existing.SourceRevision != next.SourceRevision {
			return fmt.Errorf("%w: run already names another release", ErrInvalid)
		}
	}
	return nil
}

func channelBinaryIdentities(channel Channel) (map[string]release.BinaryReceipt, error) {
	binaries := make(map[string]release.BinaryReceipt, len(channel.Receipts))
	for _, wire := range channel.Receipts {
		envelope, err := trust.DecodeEnvelope(wire)
		if err != nil {
			return nil, err
		}
		var receipt release.BinaryUpdateReceipt
		if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
			return nil, err
		}
		if _, found := binaries[receipt.Binary.GOARCH]; found {
			return nil, fmt.Errorf("%w: duplicate binary architecture", ErrInvalid)
		}
		binaries[receipt.Binary.GOARCH] = receipt.Binary
	}
	return binaries, nil
}

func ReadServiceStatus(ctx context.Context, location Location, role string) (ServiceStatus, bool, error) {
	var status ServiceStatus
	found, err := location.read(ctx, ServiceStatusObject(role), maxStatusBytes, &status)
	return status, found, err
}

// WriteServiceStatus replaces role's status; only the region's authority
// leader writes it.
func WriteServiceStatus(ctx context.Context, location Location, status ServiceStatus) error {
	status.Schema, status.Reason = ServiceStatusSchema, Clip(status.Reason)
	wire, err := json.Marshal(status, json.Deterministic(true))
	if err != nil {
		return err
	}
	return location.write(ctx, ServiceStatusObject(status.Role), wire)
}

func productionBinaryExpectation(binary BinaryReceipt, expected UpdateExpectation) ProductionExpectation {
	return ProductionExpectation{SourceRevision: binary.SourceRevision, ArtifactSHA256: binary.SHA256,
		QualificationSHA256: binary.QualificationSHA256, Cell: expected.Cell, Environment: expected.Environment,
		Runtime: ProductionRuntime, Architecture: expected.Architecture, Role: "orchestrator"}
}

// VerifyQualifiedBinaryUpdateCurrent requires both release and qualification
// authority at the consumer's current time and own target scope.
func VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation, now time.Time) (VerifiedBinary, error) {
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedBinary{}, err
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VerifiedBinary{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return VerifiedBinary{}, err
	}
	if receipt.Production == nil {
		return VerifiedBinary{}, fmt.Errorf("%w: signed update contains no independent qualification", ErrProductionQualification)
	}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots,
		productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return VerifiedBinary{}, err
	}
	qualification, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return VerifiedBinary{}, err
	}
	if qualification.ExpiresAt.Before(binary.proof.expiresAt) {
		binary.proof.expiresAt = qualification.ExpiresAt
	}
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return VerifiedBinary{}, err
		}
		if delegation.ExpiresAt.Before(binary.proof.expiresAt) {
			binary.proof.expiresAt = delegation.ExpiresAt
		}
	}
	return binary, nil
}

// AttachProductionQualification preserves source/run provenance and signs the
// independent authority's exact candidate proof into the update receipt.
func AttachProductionQualification(envelope trust.Envelope, proof ProductionProof, delegationWire []byte, roots trust.Keyring, private ed25519.PrivateKey, expected UpdateExpectation, now time.Time) (trust.Envelope, error) {
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyProductionCurrent(proof.Qualification, proof.Delegation, roots, productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return trust.Envelope{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return trust.Envelope{}, err
	}
	receipt.Production = &proof
	payload, err := trust.EncodePayload(receipt)
	if err != nil {
		return trust.Envelope{}, err
	}
	signed, err := trust.Sign(payload, envelope.Scope, envelope.IssuedAt, envelope.ExpiresAt, private)
	if err != nil {
		return trust.Envelope{}, err
	}
	wire, err = trust.EncodeEnvelope(signed)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire, roots, expected, now); err != nil {
		return trust.Envelope{}, err
	}
	return signed, nil
}

func ProductionQualificationScope(candidate ProductionExpectation) trust.Scope {
	return trust.Scope{Domain: ProductionQualificationDomain, DeploymentID: entityid.Derive("build", candidate.SourceRevision),
		Cell: candidate.Cell, Environment: candidate.Environment, Role: candidate.Role,
		Slot: candidate.Runtime + "/linux-" + candidate.Architecture}
}

// VerifyProductionCurrent accepts a trusted root or an explicitly delegated
// qualification signer. An ordinary binary-release delegation grants no authority.
// The caller must also verify the referenced retained evidence bytes.
func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}

func (delegation BinaryUpdateDelegation) Validate() error {
	if delegation.Schema != UpdateDelegationSchema || !ValidEnvironment(delegation.Environment) ||
		delegation.Repository != QualificationRepository || delegation.Workflow != QualificationWorkflow ||
		delegation.Ref != LineageRef || !revisionPattern.MatchString(delegation.LineageBase) ||
		len(delegation.Architectures) == 0 || len(delegation.Architectures) > 2 || len(delegation.Services) > maxUpdateDelegationServices {
		return fmt.Errorf("%w: binary update delegation scope", ErrInvalidReceipt)
	}
	if !sortedUnique(delegation.Architectures, func(value string) bool { return value == "amd64" || value == "arm64" }) {
		return fmt.Errorf("%w: binary update delegation architectures", ErrInvalidReceipt)
	}
	if err := validateServiceGrants(delegation.Services); err != nil {
		return err
	}
	publicKey, err := base64.RawURLEncoding.DecodeString(delegation.SubjectPublicKey)
	if err != nil || len(publicKey) != ed25519.PublicKeySize {
		return fmt.Errorf("%w: delegated public key", ErrInvalidReceipt)
	}
	keyID, err := trust.KeyID(ed25519.PublicKey(publicKey))
	if err != nil || keyID != delegation.SubjectKeyID {
		return trust.ErrKeyMismatch
	}
	return nil
}

func sortedUnique(values []string, valid func(string) bool) bool {
	for index, value := range values {
		if !valid(value) || index > 0 && values[index-1] >= value {
			return false
		}
	}
	return true
}

// validateServiceGrants requires grants sorted by strictly ascending role, so each role appears once.
func validateServiceGrants(services []ServiceGrant) error {
	for index, service := range services {
		repository, err := url.Parse(service.Repository)
		if !serviceRolePattern.MatchString(service.Role) || index > 0 && services[index-1].Role >= service.Role ||
			err != nil || repository.Scheme != "https" || repository.Host == "" || len(service.Repository) > 512 {
			return fmt.Errorf("%w: binary update delegation services", ErrInvalidReceipt)
		}
	}
	return nil
}

// MayRelease reports whether the delegation names exactly this role and repository.
func (delegation BinaryUpdateDelegation) MayRelease(role, repository string) bool {
	return slices.Contains(delegation.Services, ServiceGrant{Role: role, Repository: repository})
}

// Validate checks the receipt payload's own fields.
func (receipt BinaryUpdateReceipt) Validate() error {
	if (receipt.ReleaseSequence == 0) != (receipt.SequenceMigrationSHA256 == "") || receipt.SequenceMigrationSHA256 != "" && !digestPattern.MatchString(receipt.SequenceMigrationSHA256) {
		return fmt.Errorf("%w: release order", ErrInvalidReceipt)
	}
	if receipt.Schema != UpdateReceiptSchema || !ValidRegion(receipt.Cell) || !digestPattern.MatchString(receipt.DelegationSHA256) ||
		receipt.Lineage.Repository != QualificationRepository || receipt.Lineage.Workflow != QualificationWorkflow ||
		receipt.Lineage.Ref != LineageRef || !revisionPattern.MatchString(receipt.Lineage.LineageBase) ||
		receipt.Lineage.QualificationRunID <= 0 || receipt.Lineage.QualificationRunNum <= 0 {
		return fmt.Errorf("%w: binary update receipt scope or lineage", ErrInvalidReceipt)
	}
	return receipt.Binary.Validate()
}

// UpdateDelegationScope is the root signature scope of a delegation for one
// environment.
func UpdateDelegationScope(environment string) trust.Scope {
	return trust.Scope{
		Domain: UpdateDelegationDomain, DeploymentID: updateDelegationDeployment, Cell: updateDelegationCell,
		Environment: environment, Role: updateDelegationRole, Slot: updateDelegationSlot,
	}
}

// UpdateReceiptScope is the leaf signature scope of one update receipt.
func UpdateReceiptScope(receipt BinaryUpdateReceipt, environment string) trust.Scope {
	return trust.Scope{
		Domain: UpdateReceiptDomain, DeploymentID: entityid.Derive("build", receipt.Binary.SourceRevision), Cell: receipt.Cell,
		Environment: environment, Role: "artifact", Slot: "linux-" + receipt.Binary.GOARCH,
	}
}

// SignUpdateDelegation is the offline root operation that issues a grant.
func SignUpdateDelegation(delegation BinaryUpdateDelegation, issuedAt, expiresAt time.Time,
	rootPrivateKey ed25519.PrivateKey,
) (trust.Envelope, error) {
	if err := delegation.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if !expiresAt.After(issuedAt) || expiresAt.Sub(issuedAt) > MaxUpdateDelegationLifetime {
		return trust.Envelope{}, fmt.Errorf("binary update delegation must expire within %s", MaxUpdateDelegationLifetime)
	}
	payload, err := trust.EncodePayload(delegation)
	if err != nil {
		return trust.Envelope{}, err
	}
	return trust.Sign(payload, UpdateDelegationScope(delegation.Environment), issuedAt, expiresAt, rootPrivateKey)
}

type verifiedUpdateDelegation struct {
	delegation BinaryUpdateDelegation
	envelope   trust.Envelope
	digest     string
	publicKey  ed25519.PublicKey
}

// envelopeCheck is trust.VerifyHistorical or, through currentAt, trust.VerifyCurrent.
type envelopeCheck func(trust.Envelope, trust.Scope, trust.Keyring, trust.Policy) ([]byte, error)

func currentAt(now time.Time) envelopeCheck {
	return func(envelope trust.Envelope, scope trust.Scope, keys trust.Keyring, policy trust.Policy) ([]byte, error) {
		return trust.VerifyCurrent(envelope, scope, keys, now, policy)
	}
}

func verifyUpdateDelegation(envelope trust.Envelope, roots trust.Keyring, environment string,
	check envelopeCheck,
) (verifiedUpdateDelegation, error) {
	payload, err := check(envelope, UpdateDelegationScope(environment), roots,
		trust.Policy{MaxLifetime: MaxUpdateDelegationLifetime, ClockSkew: clockSkew})
	if err != nil {
		return verifiedUpdateDelegation{}, fmt.Errorf("verify binary update delegation: %w", err)
	}
	delegation, err := decodeCanonicalPayload[BinaryUpdateDelegation](payload)
	if err != nil {
		return verifiedUpdateDelegation{}, err
	}
	if err := delegation.Validate(); err != nil {
		return verifiedUpdateDelegation{}, err
	}
	if delegation.Environment != environment {
		return verifiedUpdateDelegation{}, ErrExpectationMismatch
	}
	digest, err := trust.Fingerprint(envelope)
	if err != nil {
		return verifiedUpdateDelegation{}, err
	}
	publicKey, _ := base64.RawURLEncoding.DecodeString(delegation.SubjectPublicKey)
	return verifiedUpdateDelegation{delegation: delegation, envelope: envelope, digest: digest, publicKey: publicKey}, nil
}

func (verified verifiedUpdateDelegation) authorize(receipt BinaryUpdateReceipt) error {
	delegation := verified.delegation
	if !slices.Contains(delegation.Architectures, receipt.Binary.GOARCH) {
		return fmt.Errorf("%w: architecture is outside the delegation", trust.ErrCapabilityDenied)
	}
	if receipt.DelegationSHA256 != verified.digest || receipt.Lineage.Repository != delegation.Repository ||
		receipt.Lineage.Workflow != delegation.Workflow || receipt.Lineage.Ref != delegation.Ref ||
		receipt.Lineage.LineageBase != delegation.LineageBase {
		return ErrLineage
	}
	return nil
}

// SignBinaryUpdateReceipt is the online leaf operation. It verifies the
// current delegation, binds the receipt to the exact qualification manifest
// and its successful ci.yml run, proves the source lineage with checker, and
// re-verifies the signed result through the consumer policy.
func SignBinaryUpdateReceipt(binary BinaryReceipt, qualification Qualification, qualificationSHA256, cell, environment string,
	checker LineageChecker, delegationEnvelope trust.Envelope, roots trust.Keyring, privateKey ed25519.PrivateKey,
	now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	return signBinaryUpdateReceipt(binary, qualification, qualificationSHA256, cell, environment, checker, delegationEnvelope, roots, privateKey, now, validFor, 0, "")
}

// SignBinaryUpdateReceiptSequenced binds the signer-owned order and its exact
// root-authorized migration without changing historical CI provenance.
func SignBinaryUpdateReceiptSequenced(binary BinaryReceipt, qualification Qualification, qualificationSHA256, cell, environment string,
	checker LineageChecker, delegationEnvelope trust.Envelope, roots trust.Keyring, privateKey ed25519.PrivateKey,
	now time.Time, validFor time.Duration, sequence uint64, migrationSHA256 string,
) (trust.Envelope, error) {
	if sequence == 0 || !digestPattern.MatchString(migrationSHA256) {
		return trust.Envelope{}, fmt.Errorf("%w: release order", ErrInvalidReceipt)
	}
	return signBinaryUpdateReceipt(binary, qualification, qualificationSHA256, cell, environment, checker, delegationEnvelope, roots, privateKey, now, validFor, sequence, migrationSHA256)
}

func signBinaryUpdateReceipt(binary BinaryReceipt, qualification Qualification, qualificationSHA256, cell, environment string,
	checker LineageChecker, delegationEnvelope trust.Envelope, roots trust.Keyring, privateKey ed25519.PrivateKey,
	now time.Time, validFor time.Duration, sequence uint64, migrationSHA256 string,
) (trust.Envelope, error) {
	if checker == nil {
		return trust.Envelope{}, fmt.Errorf("%w: no lineage checker", ErrLineage)
	}
	if validFor <= 0 || validFor > MaxUpdateReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("update receipt validity must be positive and no longer than %s", MaxUpdateReceiptLifetime)
	}
	if err := qualification.MatchBinary(binary, qualificationSHA256); err != nil {
		return trust.Envelope{}, err
	}
	verified, err := verifyUpdateDelegation(delegationEnvelope, roots, environment, currentAt(now))
	if err != nil {
		return trust.Envelope{}, err
	}
	if len(privateKey) != ed25519.PrivateKeySize {
		return trust.Envelope{}, trust.ErrKeyMismatch
	}
	signerKeyID, err := trust.KeyID(privateKey.Public().(ed25519.PublicKey))
	if err != nil || signerKeyID != verified.delegation.SubjectKeyID {
		return trust.Envelope{}, trust.ErrKeyMismatch
	}
	if err := checker.CheckLineage(verified.delegation.LineageBase, binary.SourceRevision, verified.delegation.Ref); err != nil {
		return trust.Envelope{}, fmt.Errorf("%w: %w", ErrLineage, err)
	}
	receipt := BinaryUpdateReceipt{
		Schema: UpdateReceiptSchema, Binary: binary, Cell: cell, DelegationSHA256: verified.digest,
		ReleaseSequence: sequence, SequenceMigrationSHA256: migrationSHA256,
		Lineage: SourceLineage{
			Repository: qualification.Repository, Workflow: qualification.Verification.Workflow, Ref: verified.delegation.Ref,
			LineageBase: verified.delegation.LineageBase, QualificationRunID: qualification.Verification.RunID,
			QualificationRunNum: qualification.Verification.RunNumber,
		},
	}
	if err := receipt.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if err := verified.authorize(receipt); err != nil {
		return trust.Envelope{}, err
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		// The receipt is capped at its delegation's expiry. Refuse a cap
		// that would leave a receipt consumers reject almost at once.
		if remaining := delegationEnvelope.ExpiresAt.Sub(now); remaining < min(validFor, MinUpdateReceiptValidity) {
			return trust.Envelope{}, fmt.Errorf("update delegation expires in %s, less than the %s minimum receipt validity; renew the delegation",
				remaining.Round(time.Second), min(validFor, MinUpdateReceiptValidity))
		}
		expiresAt = delegationEnvelope.ExpiresAt
	}
	payload, err := trust.EncodePayload(receipt)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(payload, UpdateReceiptScope(receipt, environment), now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelopeWire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	delegationWire, err := trust.EncodeEnvelope(delegationEnvelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyBinaryUpdateCurrent(envelopeWire, delegationWire, roots,
		UpdateExpectation{Environment: environment, Cell: cell, Architecture: binary.GOARCH}, now); err != nil {
		return trust.Envelope{}, fmt.Errorf("signed update receipt fails consumer verification: %w", err)
	}
	return envelope, nil
}

// MinUpdateReceiptValidity is the shortest validity an update receipt is
// signed with when its delegation's expiry caps the requested validity.
const MinUpdateReceiptValidity = time.Hour

// VerifyBinaryUpdateCurrent verifies an automatically signed update receipt
// against a currently valid root delegation, the consumer's environment,
// cell and architecture, and the delegation's pinned lineage. It returns the
// same VerifiedBinary type as the per-source path.
func VerifyBinaryUpdateCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected UpdateExpectation, now time.Time,
) (VerifiedBinary, error) {
	receipt, proof, err := verifyBinaryUpdate(envelopeWire, delegationWire, roots, expected, currentAt(now))
	if err != nil {
		return VerifiedBinary{}, err
	}
	return VerifiedBinary{receipt: receipt, proof: proof}, nil
}

// VerifyReleaseDelegationCurrent verifies the root-signed update delegation for
// the consumer's environment against a currently valid root. It returns the
// delegation, the leaf key it authorizes and when the grant expires.
func VerifyReleaseDelegationCurrent(delegationWire []byte, roots trust.Keyring, environment string, now time.Time,
) (BinaryUpdateDelegation, ed25519.PublicKey, time.Time, error) {
	envelope, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return BinaryUpdateDelegation{}, nil, time.Time{}, err
	}
	verified, err := verifyUpdateDelegation(envelope, roots, environment, currentAt(now))
	if err != nil {
		return BinaryUpdateDelegation{}, nil, time.Time{}, err
	}
	return verified.delegation, verified.publicKey, envelope.ExpiresAt, nil
}

// VerifyBinaryUpdateHistorical verifies that an update receipt was signed
// within its root delegation for the consumer's environment, cell and
// architecture, without requiring either to be valid now. It proves the
// identity of a binary staged earlier under a current receipt; it never
// authorizes staging.
func VerifyBinaryUpdateHistorical(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected UpdateExpectation,
) (HistoricalBinary, error) {
	receipt, proof, err := verifyBinaryUpdate(envelopeWire, delegationWire, roots, expected, trust.VerifyHistorical)
	if err != nil {
		return HistoricalBinary{}, err
	}
	return HistoricalBinary{receipt: receipt, proof: proof}, nil
}

func verifyBinaryUpdate(envelopeWire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation,
	check envelopeCheck,
) (BinaryReceipt, receiptProof, error) {
	if err := validateEnvironment(expected.Environment); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if !ValidRegion(expected.Cell) || expected.Architecture != "amd64" && expected.Architecture != "arm64" {
		return BinaryReceipt{}, receiptProof{}, fmt.Errorf("%w: update expectation", ErrExpectationMismatch)
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	verified, err := verifyUpdateDelegation(delegationEnvelope, roots, expected.Environment, check)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	receipt, err := decodeCanonicalPayload[BinaryUpdateReceipt](envelope.Payload)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if err := receipt.Validate(); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if receipt.Cell != expected.Cell || receipt.Binary.GOARCH != expected.Architecture {
		return BinaryReceipt{}, receiptProof{}, ErrExpectationMismatch
	}
	if err := verified.authorize(receipt); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if envelope.IssuedAt.Before(delegationEnvelope.IssuedAt) || envelope.ExpiresAt.After(delegationEnvelope.ExpiresAt) {
		return BinaryReceipt{}, receiptProof{}, trust.ErrDelegationTime
	}
	if _, err := check(envelope, UpdateReceiptScope(receipt, expected.Environment),
		trust.Keyring{verified.delegation.SubjectKeyID: verified.publicKey},
		trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime, ClockSkew: clockSkew}); err != nil {
		return BinaryReceipt{}, receiptProof{}, fmt.Errorf("verify binary update receipt: %w", err)
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	return receipt.Binary, proof, nil
}

func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

func (c Cell) API(part string) (string, error) {
	name, err := c.Name()
	if err != nil {
		return "", err
	}
	if part == "" {
		return name + "-api", nil
	}
	if !apiPart.MatchString(part) {
		return "", fmt.Errorf("%w: API part %q", ErrName, part)
	}
	return name + "-api-" + part, nil
}

func Validate(name string) error {
	match := nodeScheme.FindStringSubmatch(name)
	if match == nil {
		match = scheme.FindStringSubmatch(name)
	}
	if match == nil || !catalog.IsCell(strings.ToUpper(match[1])) {
		return fmt.Errorf("%w: %q", ErrName, name)
	}
	return nil
}

func valid(name string) (string, error) {
	if err := Validate(name); err != nil {
		return "", err
	}
	return name, nil
}

func ReadObject(ctx context.Context, client objectReader, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	switch sdk := client.(type) {
	case objectstorage.ObjectStorageClient:
		ConfigureReadCancellation(&sdk.BaseClient)
		return sdk.GetObject(ReadContext(ctx), request)
	case *objectstorage.ObjectStorageClient:
		copy := *sdk
		ConfigureReadCancellation(&copy.BaseClient)
		return copy.GetObject(ReadContext(ctx), request)
	default:
		return client.GetObject(ctx, request)
	}
}

func verifyFunctionChannelEntry(t *testing.T, location Location, entry FunctionRelease, roots trust.Keyring, floor uint64) {
	t.Helper()
	claim, err := entry.Claim()
	if err != nil {
		t.Fatal(err)
	}
	module, err := ReadFunctionModule(t.Context(), location, claim.Digest)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := release.VerifyFunctionCurrent(entry.Envelope, entry.Delegation, module, roots, functionExpected(claim, floor), time.Now()); err != nil {
		t.Fatal(err)
	}
}

func functionExpected(claim release.FunctionClaim, floor uint64) release.FunctionExpectation {
	return release.FunctionExpectation{Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID, FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: floor}
}

type functionChannelFixture struct {
	root  ed25519.PrivateKey
	roots trust.Keyring
}

func newFunctionChannelFixture(t *testing.T) functionChannelFixture {
	t.Helper()
	public, private, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(public)
	if err != nil {
		t.Fatal(err)
	}
	return functionChannelFixture{root: private, roots: roots}
}

func (fixture functionChannelFixture) proof(t *testing.T, tenant, function string, sequence uint64, revision string) release.VerifiedFunction {
	t.Helper()
	module := []byte("function module " + revision)
	digest := sha256.Sum256(module)
	claim := release.FunctionClaim{Schema: release.FunctionSchema, ABI: release.FunctionABI, TenantID: tenant, FunctionID: function, Revision: revision, Digest: hex.EncodeToString(digest[:]), Bytes: int64(len(module)), Environment: "production", Cell: "GRU", Sequence: sequence}
	public, private, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(public)
	if err != nil {
		t.Fatal(err)
	}
	encoded, err := trust.EncodeDelegatedPublicKey(public)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	scope := release.FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encoded, Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell, Environment: scope.Environment, Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}}}, now.Add(-time.Minute), now.Add(2*time.Hour), fixture.root)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := release.SignFunctionClaim(claim, module, delegation, fixture.roots, private, now, time.Hour)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	grant, err := trust.EncodeEnvelope(delegation)
	if err != nil {
		t.Fatal(err)
	}
	proof, err := release.VerifyFunctionCurrent(wire, grant, module, fixture.roots, functionExpected(claim, sequence), now)
	if err != nil {
		t.Fatal(err)
	}
	return proof
}

type functionObject struct {
	data    []byte
	version int
}
type functionBucketBackend struct {
	mu                      sync.Mutex
	objects                 map[string]functionObject
	dropModule, dropChannel bool
	concurrent              []byte
}

func functionObjectEndpoint(t *testing.T) (Location, *functionBucketBackend) {
	t.Helper()
	backend := &functionBucketBackend{objects: map[string]functionObject{}}
	endpoint := httptest.NewServer(http.HandlerFunc(backend.serve))
	t.Cleanup(endpoint.Close)
	key, err := rsa.GenerateKey(rand.Reader, 2048)
	if err != nil {
		t.Fatal(err)
	}
	provider := common.NewRawConfigurationProvider("ocid1.tenancy.oc1..function", "ocid1.user.oc1..function", "sa-saopaulo-1", "fp", string(pem.EncodeToMemory(&pem.Block{Type: "RSA PRIVATE KEY", Bytes: x509.MarshalPKCS1PrivateKey(key)})), nil)
	client, err := objectstorage.NewObjectStorageClientWithConfigurationProvider(provider)
	if err != nil {
		t.Fatal(err)
	}
	client.Configuration.RetryPolicy = new(common.NoRetryPolicy())
	client.Host = endpoint.URL
	return Location{Client: client, Namespace: "namespace", Bucket: "gru-1-head"}, backend
}

func (backend *functionBucketBackend) serve(w http.ResponseWriter, r *http.Request) {
	backend.mu.Lock()
	defer backend.mu.Unlock()
	_, name, ok := strings.Cut(r.URL.Path, "/o/")
	if !ok {
		http.Error(w, "route", 404)
		return
	}
	object, found := backend.objects[name]
	if r.Method == http.MethodGet {
		if !found {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(404)
			_, _ = io.WriteString(w, `{"code":"ObjectNotFound","message":"absent"}`)
			return
		}
		w.Header().Set("ETag", fmt.Sprint(object.version))
		w.Header().Set("Content-Length", fmt.Sprint(len(object.data)))
		_, _ = w.Write(object.data)
		return
	}
	if r.Method != http.MethodPut {
		http.Error(w, "method", 405)
		return
	}
	if name == FunctionChannelObject && len(backend.concurrent) > 0 {
		backend.objects[name] = functionObject{data: bytes.Clone(backend.concurrent), version: object.version + 1}
		backend.concurrent = nil
		http.Error(w, "concurrent", 412)
		return
	}
	if r.Header.Get("If-None-Match") == "*" && found || r.Header.Get("If-Match") != "" && (!found || r.Header.Get("If-Match") != fmt.Sprint(object.version)) {
		http.Error(w, "changed", 412)
		return
	}
	body, err := io.ReadAll(io.LimitReader(r.Body, release.MaxFunctionModuleBytes+1))
	if err != nil {
		http.Error(w, "read", 400)
		return
	}
	if strings.HasPrefix(name, "releases/functions/modules/") && r.Header.Get("Content-Type") != "application/wasm" {
		http.Error(w, "module type", 400)
		return
	}
	backend.objects[name] = functionObject{data: body, version: object.version + 1}
	drop := name == FunctionChannelObject && backend.dropChannel || strings.HasPrefix(name, "releases/functions/modules/") && backend.dropModule
	if drop {
		if name == FunctionChannelObject {
			backend.dropChannel = false
		} else {
			backend.dropModule = false
		}
		connection, _, err := w.(http.Hijacker).Hijack()
		if err == nil {
			_ = connection.Close()
		}
		return
	}
	w.Header().Set("ETag", fmt.Sprint(object.version+1))
	w.WriteHeader(http.StatusOK)
}

func (entry FunctionRelease) Claim() (release.FunctionClaim, error) {
	envelope, err := trust.DecodeEnvelope(entry.Envelope)
	if err != nil {
		return release.FunctionClaim{}, err
	}
	if _, err := trust.DecodeEnvelope(entry.Delegation); err != nil {
		return release.FunctionClaim{}, err
	}
	var claim release.FunctionClaim
	if err := json.Unmarshal(envelope.Payload, &claim, json.RejectUnknownMembers(true)); err != nil {
		return release.FunctionClaim{}, err
	}
	if err := claim.Validate(); err != nil {
		return release.FunctionClaim{}, err
	}
	canonical, err := trust.EncodePayload(claim)
	if err != nil || !bytes.Equal(canonical, envelope.Payload) || envelope.Scope != release.FunctionScope(claim) {
		return release.FunctionClaim{}, ErrInvalid
	}
	return claim, nil
}

// FunctionChannel is an unsigned index sorted by the signed tenant/function key.
// Entries only select candidates for current release verification.
type FunctionChannel struct {
	Schema  string            `json:"schema"`
	Entries []FunctionRelease `json:"entries"`
}

func FunctionModuleObject(digest string) string { return "releases/functions/modules/" + digest }

func decodeFunctionChannel(wire []byte) (FunctionChannel, error) {
	var channel FunctionChannel
	if len(wire) > MaxFunctionChannelBytes || json.Unmarshal(wire, &channel, json.RejectUnknownMembers(true)) != nil || channel.Schema != FunctionChannelSchema || len(channel.Entries) > MaxFunctionEntries {
		return FunctionChannel{}, ErrInvalid
	}
	previous := ""
	for _, entry := range channel.Entries {
		claim, err := entry.Claim()
		if err != nil {
			return FunctionChannel{}, err
		}
		key := functionReleaseKey(claim)
		if key <= previous {
			return FunctionChannel{}, ErrInvalid
		}
		previous = key
	}
	return channel, nil
}

func functionReleaseKey(claim release.FunctionClaim) string {
	return claim.TenantID + "." + claim.FunctionID
}

func ReadFunctionChannel(ctx context.Context, location Location) (FunctionChannel, bool, error) {
	wire, _, found, err := location.get(ctx, FunctionChannelObject, MaxFunctionChannelBytes)
	if err != nil || !found {
		return FunctionChannel{}, found, err
	}
	channel, err := decodeFunctionChannel(wire)
	return channel, true, err
}

// ReadFunctionModule bounds allocation and checks the requested immutable digest.
// A module's bytes alone authorize neither its tenant nor execution.
func ReadFunctionModule(ctx context.Context, location Location, digest string) ([]byte, error) {
	decoded, err := hex.DecodeString(digest)
	if err != nil || len(decoded) != sha256.Size || digest != strings.ToLower(digest) {
		return nil, ErrInvalid
	}
	module, _, found, err := location.get(ctx, FunctionModuleObject(digest), release.MaxFunctionModuleBytes)
	if err != nil {
		return nil, err
	}
	if !found {
		return nil, fmt.Errorf("%w: function module is absent", ErrInvalid)
	}
	sum := sha256.Sum256(module)
	if len(module) == 0 || hex.EncodeToString(sum[:]) != digest {
		return nil, fmt.Errorf("%w: function module digest mismatch", ErrInvalid)
	}
	return module, nil
}

func (location Location) read(ctx context.Context, name string, limit int64, value any) (bool, error) {
	data, _, found, err := location.get(ctx, name, limit)
	if err != nil || !found {
		return found, err
	}
	if err := json.Unmarshal(data, value); err != nil {
		return true, fmt.Errorf("%w: decode %s: %w", ErrInvalid, name, err)
	}
	return true, nil
}

func (location Location) get(ctx context.Context, name string, limit int64) ([]byte, string, bool, error) {
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{
		NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name,
	})
	if httpStatus(err) == http.StatusNotFound {
		return nil, "", false, nil
	}
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	defer response.Content.Close()
	data, err := io.ReadAll(io.LimitReader(response.Content, limit+1))
	if err != nil {
		return nil, "", false, fmt.Errorf("read %s/%s: %w", location.Bucket, name, err)
	}
	if int64(len(data)) > limit {
		return nil, "", false, fmt.Errorf("%w: %s/%s exceeds %d bytes", ErrInvalid, location.Bucket, name, limit)
	}
	if response.ETag == nil || *response.ETag == "" {
		return nil, "", false, fmt.Errorf("read %s/%s: no ETag", location.Bucket, name)
	}
	return data, *response.ETag, true, nil
}

func (claim FunctionClaim) Validate() error {
	if claim.Schema != FunctionSchema || claim.ABI != FunctionABI || !entityid.Valid(claim.TenantID) ||
		!serviceRolePattern.MatchString(claim.FunctionID) || !serviceRolePattern.MatchString(claim.Revision) ||
		!digestPattern.MatchString(claim.Digest) || claim.Bytes <= 0 || claim.Bytes > MaxFunctionModuleBytes ||
		len(claim.Capabilities) != 0 || !ValidEnvironment(claim.Environment) || !ValidRegion(claim.Cell) || claim.Sequence == 0 {
		return fmt.Errorf("%w: function ABI, identity, bytes, capabilities or release scope", ErrInvalidReceipt)
	}
	return nil
}

// FunctionScope keeps online signing grants specific to a tenant and function.
func FunctionScope(claim FunctionClaim) trust.Scope {
	return trust.Scope{
		Domain: FunctionDomain, DeploymentID: claim.TenantID, Cell: claim.Cell,
		Environment: claim.Environment, Role: "function-worker", Slot: claim.FunctionID,
	}
}

// SignFunctionClaim signs only bytes matching the claim and a current exact
// root delegation. The producer allocates Sequence durably before calling it.
func SignFunctionClaim(claim FunctionClaim, module []byte, delegation trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if err := claim.validateModule(module); err != nil {
		return trust.Envelope{}, err
	}
	return signReceipt(claim, FunctionScope(claim), delegation, roots, privateKey, now, validFor)
}

// VerifyFunctionCurrent admits portable bytes only after checking the trusted
// roots, exact signing grant, validity, expected identity, sequence and digest.
func VerifyFunctionCurrent(envelopeWire, delegationWire, module []byte, roots trust.Keyring,
	expected FunctionExpectation, now time.Time,
) (VerifiedFunction, error) {
	if err := expected.validate(); err != nil {
		return VerifiedFunction{}, err
	}
	if len(module) == 0 || len(module) > MaxFunctionModuleBytes {
		return VerifiedFunction{}, fmt.Errorf("%w: function module size", ErrInvalidReceipt)
	}
	claim, envelope, err := verifyFunctionReceipt(envelopeWire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedFunction{}, err
	}
	// Retain the copy whose digest is checked, so callers cannot mutate admitted bytes.
	admitted := bytes.Clone(module)
	if err := claim.validateModule(admitted); err != nil {
		return VerifiedFunction{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedFunction{}, err
	}
	return VerifiedFunction{claim: claim, module: admitted, envelope: bytes.Clone(envelopeWire),
		delegation: bytes.Clone(delegationWire), proof: proof}, nil
}

func (claim FunctionClaim) validateModule(module []byte) error {
	if err := claim.Validate(); err != nil {
		return err
	}
	if int64(len(module)) != claim.Bytes {
		return fmt.Errorf("%w: function module size mismatch", ErrInvalidReceipt)
	}
	digest := sha256.Sum256(module)
	if hex.EncodeToString(digest[:]) != claim.Digest {
		return fmt.Errorf("%w: function module digest mismatch", ErrInvalidReceipt)
	}
	return nil
}

// Valid rejects both forged zero values and authority that expired after admission.
func (verified VerifiedFunction) Valid() bool {
	return verified.proof.verified && time.Now().Before(verified.proof.expiresAt)
}

func (verified VerifiedFunction) Claim() FunctionClaim {
	claim := verified.claim
	claim.Capabilities = slices.Clone(claim.Capabilities)
	return claim
}

func (verified VerifiedFunction) Module() []byte         { return bytes.Clone(verified.module) }
func (verified VerifiedFunction) Envelope() []byte       { return bytes.Clone(verified.envelope) }
func (verified VerifiedFunction) Delegation() []byte     { return bytes.Clone(verified.delegation) }
func (verified VerifiedFunction) ExpiresAt() time.Time   { return verified.proof.expiresAt }
func (verified VerifiedFunction) EnvelopeSHA256() string { return verified.proof.envelopeSHA256 }

func VerifyFunctionReceiptCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected FunctionExpectation, now time.Time,
) (VerifiedFunctionReceipt, error) {
	if err := expected.validate(); err != nil {
		return VerifiedFunctionReceipt{}, err
	}
	claim, envelope, err := verifyFunctionReceipt(envelopeWire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedFunctionReceipt{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedFunctionReceipt{}, err
	}
	return VerifiedFunctionReceipt{claim: claim, proof: proof}, nil
}

func (expected FunctionExpectation) validate() error {
	if !ValidEnvironment(expected.Environment) || !ValidRegion(expected.Cell) || !entityid.Valid(expected.TenantID) ||
		!serviceRolePattern.MatchString(expected.FunctionID) || !serviceRolePattern.MatchString(expected.Revision) ||
		!digestPattern.MatchString(expected.Digest) || expected.MinimumSequence == 0 {
		return fmt.Errorf("%w: invalid function expectation or missing durable sequence floor", ErrExpectationMismatch)
	}
	return nil
}

func verifyFunctionReceipt(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected FunctionExpectation, now time.Time,
) (FunctionClaim, trust.Envelope, error) {
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	claim, err := decodeCanonicalPayload[FunctionClaim](envelope.Payload)
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	if err := claim.Validate(); err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	if claim.Environment != expected.Environment || claim.Cell != expected.Cell || claim.TenantID != expected.TenantID ||
		claim.FunctionID != expected.FunctionID || claim.Revision != expected.Revision || claim.Digest != expected.Digest ||
		claim.Sequence < expected.MinimumSequence {
		return FunctionClaim{}, trust.Envelope{}, ErrExpectationMismatch
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, fmt.Errorf("verify current function delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, FunctionScope(claim), delegation, now, receiptPolicy()); err != nil {
		return FunctionClaim{}, trust.Envelope{}, fmt.Errorf("verify current function claim: %w", err)
	}
	return claim, envelope, nil
}

func signReceipt(payload any, scope trust.Scope, delegationEnvelope trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and no longer than %s", MaxReceiptLifetime)
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return trust.Envelope{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		expiresAt = delegationEnvelope.ExpiresAt
	}
	if !expiresAt.After(now) {
		return trust.Envelope{}, trust.ErrExpired
	}
	encodedPayload, err := trust.EncodePayload(payload)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(encodedPayload, scope, now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return trust.Envelope{}, fmt.Errorf("release signer is not delegated for this exact scope: %w", err)
	}
	return envelope, nil
}

func decodeEnvelopePair(envelopeWire, delegationWire []byte) (trust.Envelope, trust.Envelope, error) {
	envelope, err := trust.DecodeEnvelope(envelopeWire)
	if err != nil {
		return trust.Envelope{}, trust.Envelope{}, err
	}
	delegation, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return trust.Envelope{}, trust.Envelope{}, fmt.Errorf("decode release delegation: %w", err)
	}
	return envelope, delegation, nil
}

func decodeCanonicalPayload[T any](encoded []byte) (T, error) {
	var value T
	if len(encoded) == 0 || len(encoded) > trust.MaxPayloadBytes {
		return value, fmt.Errorf("%w: receipt payload size", ErrInvalidReceipt)
	}
	if err := protocol.DecodeStrict(encoded, &value, trust.MaxPayloadBytes); err != nil {
		return value, fmt.Errorf("decode release receipt payload: %w", err)
	}
	canonical, err := trust.EncodePayload(value)
	if err != nil {
		return value, err
	}
	if !bytes.Equal(canonical, encoded) {
		return value, fmt.Errorf("%w: payload is not canonical JSON", ErrInvalidReceipt)
	}
	return value, nil
}

func proofFor(envelope trust.Envelope) (receiptProof, error) {
	fingerprint, err := trust.Fingerprint(envelope)
	if err != nil {
		return receiptProof{}, err
	}
	if !digestPattern.MatchString(fingerprint) {
		return receiptProof{}, fmt.Errorf("%w: canonical envelope fingerprint", ErrInvalidReceipt)
	}
	return receiptProof{
		envelopeSHA256: fingerprint, keyID: envelope.KeyID,
		issuedAt: envelope.IssuedAt, expiresAt: envelope.ExpiresAt, verified: true,
	}, nil
}

func delegationPolicy() trust.Policy {
	return trust.Policy{MaxLifetime: MaxDelegationLifetime, ClockSkew: clockSkew}
}

func receiptPolicy() trust.Policy {
	return trust.Policy{MaxLifetime: MaxReceiptLifetime, ClockSkew: clockSkew}
}

func ReadObject(ctx context.Context, client objectReader, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	switch sdk := client.(type) {
	case objectstorage.ObjectStorageClient:
		ConfigureReadCancellation(&sdk.BaseClient)
		return sdk.GetObject(ReadContext(ctx), request)
	case *objectstorage.ObjectStorageClient:
		copy := *sdk
		ConfigureReadCancellation(&copy.BaseClient)
		return copy.GetObject(ReadContext(ctx), request)
	default:
		return client.GetObject(ctx, request)
	}
}

// RequestContext keeps the SDK retry goroutine joined while the original context
// cancels the HTTP request and backoff. Use with ConfigureRequestCancellation.
func RequestContext(ctx context.Context) context.Context {
	if originalReadContext(ctx) != nil && ctx.Done() == nil {
		return ctx
	}
	return context.WithValue(context.WithoutCancel(ctx), readContextKey{}, ctx)
}

// ReadContext is RequestContext for existing read callers.
func ReadContext(ctx context.Context) context.Context { return RequestContext(ctx) }

type readContextKey struct{}

func originalReadContext(ctx context.Context) context.Context {
	original, _ := ctx.Value(readContextKey{}).(context.Context)
	return original
}

// ConfigureReadCancellation is retained for existing read callers.
func ConfigureReadCancellation(client *common.BaseClient) { ConfigureRequestCancellation(client) }

// ConfigureRequestCancellation must run after other interceptors are installed.
// It avoids the SDK Retry response race while preserving wire cancellation.
func ConfigureRequestCancellation(client *common.BaseClient) {
	if readCancellationConfigured(client.HTTPClient) {
		return
	}
	previous := client.Interceptor
	client.Interceptor = func(request *http.Request) error {
		if original := originalReadContext(request.Context()); original != nil {
			*request = *request.WithContext(context.WithValue(original, readContextKey{}, original))
		}
		if previous != nil {
			return previous(request)
		}
		return request.Context().Err()
	}
	client.HTTPClient = readDispatcher{next: client.HTTPClient}
}

func readCancellationConfigured(dispatcher common.HTTPRequestDispatcher) bool {
	switch dispatcher := dispatcher.(type) {
	case readDispatcher:
		return true
	case *instrumentedDispatcher:
		return readCancellationConfigured(dispatcher.next)
	default:
		return false
	}
}

type readDispatcher struct{ next common.HTTPRequestDispatcher }

type readTransportError struct {
	err error
	ctx context.Context
}

func (e *readTransportError) Error() string { return e.err.Error() }
func (e *readTransportError) Unwrap() error { return e.err }

func (d readDispatcher) Do(request *http.Request) (*http.Response, error) {
	var finish func(*http.Response, error, bool) error
	if request.Method != http.MethodGet && request.Method != http.MethodHead && request.Method != http.MethodOptions {
		deadline := new(admissionDeadline)
		*request = *request.WithContext(context.WithValue(request.Context(), admissionDeadlineKey{}, deadline))
		if begin, ok := request.Context().Value(wireAttemptKey{}).(func(*http.Request) (func(*http.Response, error, bool) error, error)); ok {
			if begin == nil {
				return nil, errors.New("OCI wire attempt journal is unavailable")
			}
			var err error
			finish, err = begin(request)
			if err != nil {
				return nil, fmt.Errorf("OCI wire attempt checkpoint: %w", err)
			}
			if finish == nil {
				return nil, errors.New("OCI wire attempt journal lacks outcome recorder")
			}
		}
		deny := func(err error) (*http.Response, error) {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, err
		}
		if finish != nil {
			if err := request.Context().Err(); err != nil {
				return deny(err)
			}
			// The durable begin may block; refresh the claim after that write.
			if guard, ok := request.Context().Value(authorityKey{}).(func(context.Context) error); ok {
				if guard == nil {
					return deny(errors.New("OCI wire authority is unavailable"))
				}
				if err := guard(request.Context()); err != nil {
					return deny(fmt.Errorf("OCI wire authority: %w", err))
				}
			}
		}
		if acquire, ok := request.Context().Value(admissionKey{}).(func(context.Context) (func(), error)); ok {
			if acquire == nil {
				return deny(errors.New("OCI write admission is unavailable"))
			}
			release, err := acquire(request.Context())
			if err != nil {
				return deny(fmt.Errorf("OCI write admission: %w", err))
			}
			if release == nil {
				return deny(errors.New("OCI write admission did not fence current authority"))
			}
			defer release()
		}
		if err := request.Context().Err(); err != nil {
			return deny(err)
		}
		if !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
			return deny(errors.New("OCI current admission facts expired before dispatch"))
		}
	}
	if guard, ok := request.Context().Value(requestGuardKey{}).(func(context.Context) error); ok {
		var err error
		if guard == nil {
			err = errors.New("OCI request session is unavailable")
		} else {
			// Authorization may itself read OCI; those reads must not recurse
			// into the guard they are currently establishing.
			err = guard(context.WithValue(request.Context(), requestGuardKey{}, struct{}{}))
		}
		if err != nil {
			if finish != nil {
				err = errors.Join(err, finish(nil, err, false))
			}
			return nil, &readTransportError{err: err, ctx: request.Context()}
		}
	}
	// The final source guard may wait past a shorter retained admission cap.
	// Recheck it after that wait, immediately before the actual dispatch.
	finalErr := request.Context().Err()
	if deadline, ok := request.Context().Value(admissionDeadlineKey{}).(*admissionDeadline); ok && !deadline.until.IsZero() && !time.Now().Before(deadline.until) {
		finalErr = errors.Join(finalErr, errors.New("OCI original admission deadline expired during final source guard"))
	}
	if finalErr != nil {
		if finish != nil {
			finalErr = errors.Join(finalErr, finish(nil, finalErr, false))
		}
		return nil, &readTransportError{err: finalErr, ctx: request.Context()}
	}
	response, err := d.next.Do(request)
	if finish != nil {
		if recordErr := finish(response, err, true); recordErr != nil {
			if response != nil && response.Body != nil {
				_ = response.Body.Close()
			}
			err = errors.Join(err, fmt.Errorf("OCI wire outcome remains unknown: %w", recordErr))
		}
	}
	if original := originalReadContext(request.Context()); original != nil && err != nil {
		return response, &readTransportError{err: err, ctx: original}
	}
	return response, err
}

func KeyID(publicKey ed25519.PublicKey) (string, error) {
	return protocol.KeyID(publicKey)
}

// EncodePayload emits deterministic JSON for a signed payload.
func EncodePayload(value any) ([]byte, error) {
	encoded, err := json.Marshal(value, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust payload: %w", err)
	}
	if err := validatePayload(encoded); err != nil {
		return nil, err
	}
	return encoded, nil
}

// Sign signs a strict, bounded JSON object for the exact supplied scope.
func Sign(payload []byte, scope Scope, issuedAt, expiresAt time.Time, privateKey ed25519.PrivateKey) (Envelope, error) {
	if len(privateKey) != ed25519.PrivateKeySize {
		return Envelope{}, fmt.Errorf("%w: invalid Ed25519 private key", ErrInvalid)
	}
	if err := scope.validate(); err != nil {
		return Envelope{}, err
	}
	compact, err := compactPayload(payload)
	if err != nil {
		return Envelope{}, err
	}
	issuedAt = issuedAt.Round(0).UTC()
	expiresAt = expiresAt.Round(0).UTC()
	if !validTime(issuedAt) || !validTime(expiresAt) || !expiresAt.After(issuedAt) {
		return Envelope{}, fmt.Errorf("%w: invalid trust validity interval", ErrInvalid)
	}
	publicKey := privateKey.Public().(ed25519.PublicKey)
	keyID, err := KeyID(publicKey)
	if err != nil {
		return Envelope{}, err
	}
	envelope := Envelope{
		SchemaVersion: SchemaVersion,
		KeyID:         keyID,
		Scope:         scope,
		IssuedAt:      issuedAt,
		ExpiresAt:     expiresAt,
		Payload:       compact,
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return Envelope{}, err
	}
	envelope.Signature = base64.RawURLEncoding.EncodeToString(ed25519.Sign(privateKey, material))
	return envelope, nil
}

// EncodeEnvelope emits the single deterministic JSON wire representation.
func EncodeEnvelope(envelope Envelope) ([]byte, error) {
	if err := envelope.validateShape(); err != nil {
		return nil, err
	}
	encoded, err := json.Marshal(envelope, json.Deterministic(true))
	if err != nil {
		return nil, fmt.Errorf("encode trust envelope: %w", err)
	}
	if len(encoded) > MaxEnvelopeBytes {
		return nil, fmt.Errorf("%w: encoded envelope exceeds size limit", ErrInvalid)
	}
	return encoded, nil
}

// DecodeEnvelope strictly decodes one canonical wire envelope. Unknown or
// duplicate fields, alternate outer JSON encodings, and oversized payloads fail.
func DecodeEnvelope(encoded []byte) (Envelope, error) {
	if len(encoded) == 0 || len(encoded) > MaxEnvelopeBytes {
		return Envelope{}, fmt.Errorf("%w: envelope is empty or too large", ErrInvalid)
	}
	var envelope Envelope
	if err := protocol.DecodeStrict(encoded, &envelope, MaxEnvelopeBytes); err != nil {
		return Envelope{}, fmt.Errorf("decode trust envelope: %w", err)
	}
	canonical, err := EncodeEnvelope(envelope)
	if err != nil {
		return Envelope{}, err
	}
	if string(canonical) != string(encoded) {
		return Envelope{}, fmt.Errorf("%w: envelope JSON is not canonical", ErrInvalid)
	}
	return envelope, nil
}

// VerifyCurrent verifies the exact scope, signature, lifetime, and current
// validity. Use this API before any current mutation or secret retrieval.
func VerifyCurrent(envelope Envelope, expected Scope, keys Keyring, now time.Time, policy Policy) ([]byte, error) {
	if !validTime(now) || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Sub(now) > policy.ClockSkew {
		return nil, ErrNotYetValid
	}
	if !now.Before(envelope.ExpiresAt) {
		return nil, ErrExpired
	}
	return bytesClone(envelope.Payload), nil
}

// VerifyHistorical verifies scope, signature, key, and the bounded signed
// interval but deliberately makes no current-authorization claim.
func VerifyHistorical(envelope Envelope, expected Scope, keys Keyring, policy Policy) ([]byte, error) {
	if policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	return bytesClone(envelope.Payload), nil
}

// SignDelegation signs root-controlled delegated key capabilities.
func SignDelegation(delegation Delegation, issuedAt, expiresAt time.Time, rootPrivateKey ed25519.PrivateKey) (Envelope, error) {
	if err := delegation.Validate(); err != nil {
		return Envelope{}, err
	}
	payload, err := EncodePayload(delegation)
	if err != nil {
		return Envelope{}, err
	}
	return Sign(payload, delegationScope(), issuedAt, expiresAt, rootPrivateKey)
}

// VerifyDelegationCurrent verifies a root-signed delegation and requires it to
// be currently valid before the key can authorize a current action.
func VerifyDelegationCurrent(envelope Envelope, roots Keyring, now time.Time, policy Policy) (VerifiedDelegation, error) {
	payload, err := VerifyCurrent(envelope, delegationScope(), roots, now, policy)
	if err != nil {
		return VerifiedDelegation{}, err
	}
	return decodeVerifiedDelegation(envelope, payload)
}

// VerifyDelegationHistorical validates the delegation signature and bounded
// interval without granting present-day authority.
func VerifyDelegationHistorical(envelope Envelope, roots Keyring, policy Policy) (VerifiedDelegation, error) {
	payload, err := VerifyHistorical(envelope, delegationScope(), roots, policy)
	if err != nil {
		return VerifiedDelegation{}, err
	}
	return decodeVerifiedDelegation(envelope, payload)
}

// VerifyDelegatedCurrent enforces current signer authority, key delegation
// validity, and exact capability scope.
func VerifyDelegatedCurrent(envelope Envelope, expected Scope, delegation VerifiedDelegation, now time.Time, policy Policy) ([]byte, error) {
	if !now.Before(delegation.expiresAt) || now.Add(policy.ClockSkew).Before(delegation.issuedAt) {
		return nil, ErrExpired
	}
	if err := delegation.authorize(expected); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Before(delegation.issuedAt) || envelope.ExpiresAt.After(delegation.expiresAt) {
		return nil, ErrDelegationTime
	}
	return VerifyCurrent(envelope, expected, Keyring{delegation.keyID: delegation.publicKey}, now, policy)
}

// VerifyDelegatedHistorical proves the key was delegated for the exact scope
// when the immutable record was signed; it does not authorize a new action.
func VerifyDelegatedHistorical(envelope Envelope, expected Scope, delegation VerifiedDelegation, policy Policy) ([]byte, error) {
	if err := delegation.authorize(expected); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Before(delegation.issuedAt) || envelope.ExpiresAt.After(delegation.expiresAt) {
		return nil, ErrDelegationTime
	}
	return VerifyHistorical(envelope, expected, Keyring{delegation.keyID: delegation.publicKey}, policy)
}

func (delegation Delegation) Validate() error {
	if delegation.SchemaVersion != SchemaVersion || len(delegation.Capabilities) == 0 || len(delegation.Capabilities) > maxDelegationCapabilities {
		return fmt.Errorf("%w: delegation version or capability count", ErrInvalid)
	}
	publicKey, err := base64.RawURLEncoding.DecodeString(delegation.SubjectPublicKey)
	if err != nil || len(publicKey) != ed25519.PublicKeySize {
		return fmt.Errorf("%w: delegated public key", ErrInvalid)
	}
	keyID, err := KeyID(ed25519.PublicKey(publicKey))
	if err != nil || keyID != delegation.SubjectKeyID {
		return ErrKeyMismatch
	}
	seenCapabilities := make(map[string]struct{}, len(delegation.Capabilities))
	for _, capability := range delegation.Capabilities {
		if err := capability.validate(); err != nil {
			return err
		}
		encoded, err := EncodePayload(capability)
		if err != nil {
			return err
		}
		if _, exists := seenCapabilities[string(encoded)]; exists {
			return fmt.Errorf("%w: duplicate delegation capability", ErrInvalid)
		}
		seenCapabilities[string(encoded)] = struct{}{}
	}
	return nil
}

func (capability Capability) validate() error {
	if !domainRE.MatchString(capability.Domain) || capability.Domain == DelegationDomain ||
		!entityid.Valid(capability.DeploymentID) || !cellRE.MatchString(capability.Cell) ||
		!tokenRE.MatchString(capability.Environment) || !tokenRE.MatchString(capability.Role) ||
		len(capability.Slots) == 0 || len(capability.Slots) > maxCapabilitySlots || len(capability.Actions) != 1 || capability.Actions[0] != "sign" {
		return fmt.Errorf("%w: invalid delegation capability", ErrInvalid)
	}
	seenSlots := make(map[string]struct{}, len(capability.Slots))
	for _, slot := range capability.Slots {
		if !slotRE.MatchString(slot) {
			return fmt.Errorf("%w: invalid capability slot", ErrInvalid)
		}
		if _, exists := seenSlots[slot]; exists {
			return fmt.Errorf("%w: duplicate capability slot", ErrInvalid)
		}
		seenSlots[slot] = struct{}{}
	}
	return nil
}

func (delegation VerifiedDelegation) authorize(scope Scope) error {
	if err := scope.validate(); err != nil {
		return err
	}
	for _, capability := range delegation.capabilities {
		if capability.Domain == scope.Domain && capability.DeploymentID == scope.DeploymentID && capability.Cell == scope.Cell &&
			capability.Environment == scope.Environment && capability.Role == scope.Role && slices.Contains(capability.Slots, scope.Slot) && slices.Contains(capability.Actions, "sign") {
			return nil
		}
	}
	return ErrCapabilityDenied
}

func decodeVerifiedDelegation(envelope Envelope, payload []byte) (VerifiedDelegation, error) {
	var delegation Delegation
	if err := protocol.DecodeStrict(payload, &delegation, MaxPayloadBytes); err != nil {
		return VerifiedDelegation{}, fmt.Errorf("decode trust delegation: %w", err)
	}
	if err := delegation.Validate(); err != nil {
		return VerifiedDelegation{}, err
	}
	publicKey, _ := base64.RawURLEncoding.DecodeString(delegation.SubjectPublicKey)
	return VerifiedDelegation{
		keyID: delegation.SubjectKeyID, publicKey: ed25519.PublicKey(publicKey),
		capabilities: delegation.Capabilities, issuedAt: envelope.IssuedAt, expiresAt: envelope.ExpiresAt,
	}, nil
}

func verifySignature(envelope Envelope, expected Scope, keys Keyring, maximumLifetime time.Duration) error {
	if err := envelope.validateShape(); err != nil {
		return err
	}
	if err := expected.validate(); err != nil {
		return err
	}
	if envelope.Scope != expected {
		return ErrScopeMismatch
	}
	if !envelope.ExpiresAt.After(envelope.IssuedAt) || envelope.ExpiresAt.Sub(envelope.IssuedAt) > maximumLifetime {
		return fmt.Errorf("%w: invalid or excessive trust validity interval", ErrInvalid)
	}
	publicKey, exists := keys[envelope.KeyID]
	if !exists {
		return ErrUntrustedKey
	}
	keyID, err := KeyID(publicKey)
	if err != nil {
		return err
	}
	if keyID != envelope.KeyID {
		return ErrKeyMismatch
	}
	material, err := signingMaterial(envelope)
	if err != nil {
		return err
	}
	signature, err := decodeCanonicalSignature(envelope.Signature)
	if err != nil || !ed25519.Verify(publicKey, material, signature) {
		return ErrBadSignature
	}
	return nil
}

func (envelope Envelope) validateShape() error {
	if envelope.SchemaVersion != SchemaVersion || !domainRE.MatchString(envelope.Scope.Domain) || envelope.KeyID == "" || envelope.Signature == "" ||
		!canonicalTime(envelope.IssuedAt) || !canonicalTime(envelope.ExpiresAt) {
		return fmt.Errorf("%w: envelope header", ErrInvalid)
	}
	if _, err := decodeCanonicalSignature(envelope.Signature); err != nil {
		return err
	}
	if err := envelope.Scope.validate(); err != nil {
		return err
	}
	_, err := compactPayload(envelope.Payload)
	return err
}

func (scope Scope) validate() error {
	if !domainRE.MatchString(scope.Domain) {
		return fmt.Errorf("%w: scope domain", ErrInvalid)
	}
	if scope.Domain == DelegationDomain && scope == delegationScope() {
		return nil
	}
	if !entityid.Valid(scope.DeploymentID) || !cellRE.MatchString(scope.Cell) ||
		!tokenRE.MatchString(scope.Environment) || !tokenRE.MatchString(scope.Role) || !slotRE.MatchString(scope.Slot) {
		return fmt.Errorf("%w: incomplete or invalid scope", ErrInvalid)
	}
	return nil
}

func delegationScope() Scope {
	return Scope{
		Domain: DelegationDomain, DeploymentID: DelegationDeploymentID, Cell: delegationCell,
		Environment: delegationEnvironment, Role: delegationRole, Slot: delegationSlot,
	}
}

func compactPayload(payload []byte) (jsontext.Value, error) {
	if len(payload) == 0 || len(payload) > MaxPayloadBytes || !utf8.Valid(payload) {
		return nil, fmt.Errorf("%w: payload is empty, invalid UTF-8, or too large", ErrInvalid)
	}
	value := jsontext.Value(payload).Clone()
	if err := value.Compact(jsontext.AllowDuplicateNames(false), jsontext.AllowInvalidUTF8(false)); err != nil {
		return nil, fmt.Errorf("%w: invalid payload JSON: %v", ErrInvalid, err)
	}
	if len(value) == 0 || value.Kind() != jsontext.Kind('{') {
		return nil, fmt.Errorf("%w: payload must be a JSON object", ErrInvalid)
	}
	return value, nil
}

func validatePayload(payload []byte) error {
	_, err := compactPayload(payload)
	return err
}

func signingMaterial(envelope Envelope) ([]byte, error) {
	payload, err := compactPayload(envelope.Payload)
	if err != nil {
		return nil, err
	}
	material := make([]byte, 0, len(signatureDomain)+256+sha256.Size)
	material = append(material, signatureDomain...)
	material = binary.BigEndian.AppendUint16(material, uint16(envelope.SchemaVersion))
	for _, field := range []string{
		envelope.KeyID, envelope.Scope.Domain, envelope.Scope.DeploymentID, envelope.Scope.Cell,
		envelope.Scope.Environment, envelope.Scope.Role, envelope.Scope.Slot,
		envelope.IssuedAt.Format(time.RFC3339Nano), envelope.ExpiresAt.Format(time.RFC3339Nano),
	} {
		if len(field) > 1<<16-1 {
			return nil, fmt.Errorf("%w: signed field exceeds limit", ErrInvalid)
		}
		material = binary.BigEndian.AppendUint16(material, uint16(len(field)))
		material = append(material, field...)
	}
	payloadDigest := sha256.Sum256(payload)
	material = append(material, payloadDigest[:]...)
	return material, nil
}

func validTime(value time.Time) bool {
	return !value.IsZero() && value.Year() >= 1 && value.Year() <= 9999
}

func canonicalTime(value time.Time) bool {
	return validTime(value) && value.Location() == time.UTC &&
		value.Format(time.RFC3339Nano) == value.UTC().Format(time.RFC3339Nano)
}

func decodeCanonicalSignature(encoded string) ([]byte, error) {
	signature, err := base64.RawURLEncoding.Strict().DecodeString(encoded)
	if err != nil || len(signature) != ed25519.SignatureSize || base64.RawURLEncoding.EncodeToString(signature) != encoded {
		return nil, ErrBadSignature
	}
	return signature, nil
}

func bytesClone(value []byte) []byte { return append([]byte(nil), value...) }

// DelegatedKeyID creates the key ID stored alongside a delegated public key.
func DelegatedKeyID(publicKey ed25519.PublicKey) (string, error) {
	return KeyID(publicKey)
}

// EncodeDelegatedPublicKey uses the canonical unpadded URL-safe Base64 form.
func EncodeDelegatedPublicKey(publicKey ed25519.PublicKey) (string, error) {
	if len(publicKey) != ed25519.PublicKeySize {
		return "", fmt.Errorf("%w: invalid Ed25519 public key", ErrInvalid)
	}
	return base64.RawURLEncoding.EncodeToString(publicKey), nil
}

// ParseKeyring validates baked-in root public keys and derives their full IDs.
func ParseKeyring(publicKeys ...ed25519.PublicKey) (Keyring, error) {
	keyring := make(Keyring, len(publicKeys))
	for _, publicKey := range publicKeys {
		keyID, err := KeyID(publicKey)
		if err != nil {
			return nil, err
		}
		if _, exists := keyring[keyID]; exists {
			return nil, fmt.Errorf("%w: duplicate trusted root", ErrInvalid)
		}
		keyring[keyID] = append(ed25519.PublicKey(nil), publicKey...)
	}
	if len(keyring) == 0 {
		return nil, fmt.Errorf("%w: empty trusted root set", ErrInvalid)
	}
	return keyring, nil
}

// String returns a non-secret representation useful in diagnostics.
func (scope Scope) String() string {
	return strings.Join([]string{scope.Domain, scope.DeploymentID, scope.Cell, scope.Environment, scope.Role, scope.Slot}, "/")
}

// Fingerprint returns the SHA-256 digest of canonical encoded envelope bytes.
func Fingerprint(envelope Envelope) (string, error) {
	encoded, err := EncodeEnvelope(envelope)
	if err != nil {
		return "", err
	}
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:]), nil
}
